// Üretilen dosya: tool/ozgun/uret.py. Ekonomi ve Finans · İşletme yönetimi ve pazarlama (orta).
const ozEconomics13Orta = <(String, String, List<String>, String)>[
  ('Locke\'un amaç belirleme kuramına göre hangi tür hedefler en yüksek performansı sağlar?', 'Belirgin, zor ama ulaşılabilir ve geri bildirimle desteklenen hedefler', ['Genel ve belirsiz, \'elinden geleni yap\' türü hedefler', 'Çok kolay ve herkesin rahatça tutturabileceği hedefler', 'Ulaşılması imkânsız denli yüksek konan hedefler'], 'Araştırmalar belirgin ve zorlayıcı hedeflerin, kabul edildiğinde ve geri bildirim eşlik ettiğinde \'elinden geleni yap\' hedeflerinden daha yüksek performans verdiğini gösterir.'),
  ('William Ouchi\'nin Z kuramı hangi işletme geleneğinden esinlenmiştir?', 'Japon işletmelerindeki uzun süreli istihdam ve ortak karar alma uygulamalarından', ['Alman şirketlerindeki sıkı hiyerarşiden', 'Amerikan şirketlerindeki kısa dönemli işe alım anlayışından', 'İskandinav kooperatiflerindeki eşit ücret uygulamasından'], 'Ouchi, Japon firmalarının uzun dönemli istihdam, ortak karar alma ve çalışana bütüncül ilgi gibi özelliklerini Amerikan işletmelerine uyarlanabilir bir model olarak sunmuştur.'),
  ('Öğretmenlerin \'başarılı olacak\' diye düşündüğü öğrencilerin gerçekten daha başarılı olması, yönetimde hangi kavramla paralellik taşır?', 'Pygmalion (kendini doğrulayan kehanet) etkisi', ['Hawthorne etkisi', 'Halo etkisi', 'Peter ilkesi'], 'Yöneticinin çalışandan yüksek beklenti taşıması, onun davranışını ve çalışanın özgüvenini etkileyerek beklentiyi gerçekleştirebilir; buna Pygmalion etkisi denir.'),
  ('Belbin\'in takım rollerinden \'Fikir Üretici (Plant)\' rolü üstlenen kişinin takıma temel katkısı nedir?', 'Yaratıcı ve özgün fikirler üretmesi', ['Görevlerin tamamlanmasını titizlikle izlemesi', 'Dış çevreyle ilişki ve iş bağlantıları kurması', 'Üyelerin farklı görüşlerini uzlaştırması'], 'Fikir üretici, problemlere alışılmadık çözümler getiren yaratıcı üyedir; bağlantı kurma kaynak araştırmacının, takip ise tamamlayıcı-bitirici rolün işidir.'),
  ('Irving Janis\'in \'grup düşüncesi\' kavramı hangi durumu anlatır?', 'Uyum baskısı yüzünden grubun eleştirel değerlendirmeyi bırakıp zayıf kararlar alması', ['Grubun bireylerden daha yaratıcı fikirler üretmesi', 'Grup liderinin kararları tek başına alması', 'Grup üyelerinin kararlardan sonra sorumluluğu yüklenmemesi'], 'Grup düşüncesinde uyum arzusu, farklı görüşlerin dile getirilmesini bastırır ve grup, alternatifleri yeterince tartışmadan hatalı bir karara varabilir.'),
  ('Birbirinden habersiz uzmanların soru formlarını birkaç tur yanıtlayıp özet sonuçlara göre görüşlerini gözden geçirdiği tahmin yöntemi hangisidir?', 'Delphi tekniği', ['SWOT analizi', 'Senaryo planlaması', 'Pareto analizi'], 'Delphi tekniğinde uzmanlar anonim kalır; her turda grup özeti paylaşılır ve görüşler yakınsayana kadar yinelenir. Böylece baskın kişilerin etkisi azalır.'),
  ('Hofstede\'nin kültürel boyutlarından \'güç mesafesi\' yüksek olan bir toplumda çalışanlardan hangi tutum beklenir?', 'Hiyerarşiyi ve yöneticinin otoritesini doğal kabul etmeleri', ['Yöneticilerin kararlarını açıkça sorgulamaları', 'Tüm kararların eşit oyla alınmasını istemeleri', 'Unvan ve makam farklarının önemsenmemesi'], 'Güç mesafesi, toplumdaki az güçlü bireylerin gücün eşitsiz dağılımını kabul etme derecesidir; yüksek olduğunda hiyerarşi ve otorite doğal karşılanır.'),
  ('Hofstede\'ye göre bireyciliğin yüksek olduğu bir ülkedeki işletmede aşağıdakilerden hangisinin daha fazla görülmesi beklenir?', 'Bireysel başarıya dayalı ödüllendirme ve kişisel hedefler', ['Aile ve grup çıkarını öne alan kararlar', 'Grup sadakatine dayalı terfi sistemi', 'Bireysel görüşün grup uyumu uğruna bastırılması'], 'Bireyci kültürlerde kişisel başarı, özerklik ve kişisel hedefler ön plandadır; toplulukçu kültürlerde ise grup sadakati ve uyum öne çıkar.'),
  ('Hersey ve Blanchard\'ın durumsal liderlik modelinde liderlik tarzını belirleyen temel etken nedir?', 'Takipçilerin görevi yapmaya ilişkin hazır oluş (olgunluk) düzeyi', ['Liderin yaşı ve kıdemi', 'Örgütün yıllık ciro büyüklüğü', 'Çalışanların ücret düzeyi'], 'Modelde lider, takipçilerin yetenek ve istekliliğine göre yönlendirme, ikna etme, katılımcı olma ve devretme tarzları arasında geçiş yapar.'),
  ('French ve Raven\'ın güç kaynakları sınıflandırmasında, kişinin hayranlık duyulması ve örnek alınması nedeniyle sahip olduğu güç hangisidir?', 'Referans (karizmatik) gücü', ['Yasal güç', 'Ödüllendirme gücü', 'Zorlayıcı güç'], 'Referans gücü, başkalarının kişiyi sevmesi, benimsemesi ve onunla özdeşleşmesinden doğar; makama bağlı yasal güçten farklıdır.'),
  ('Daniel Goleman\'ın duygusal zekâ modelinde \'öz farkındalık\' becerisi neyi ifade eder?', 'Kişinin kendi duygularını ve bunların davranışına etkisini tanıması', ['Başkalarının duygularını okuyup uygun karşılık vermesi', 'Duygusal tepkilerini bastırarak hiç belli etmemesi', 'Grup çatışmalarını arabuluculukla çözmesi'], 'Öz farkındalık, duygusal zekânın temelidir: kişi kendi duygu, güçlü ve zayıf yönlerini bilir. Başkalarının duygusunu anlamak ise empati başlığına girer.'),
  ('Burns ve Stalker\'a göre istikrarsız ve hızlı değişen bir çevrede hangi örgüt yapısı daha başarılıdır?', 'Esnek, yetkinin dağıldığı organik yapı', ['Sıkı kurallı ve hiyerarşik mekanik yapı', 'Tek kişinin karar verdiği merkezî yapı', 'Görev tanımları kesin çizilmiş bürokratik yapı'], 'Burns ve Stalker, durağan çevrede mekanik, değişken çevrede ise esnek ve yatay iletişime dayalı organik yapıların daha uygun olduğunu bulmuştur.'),
  ('Laurence Peter\'ın \'Peter ilkesi\' neyi öne sürer?', 'Hiyerarşide herkes yetersiz kalacağı kademeye kadar yükselme eğilimindedir', ['Her çalışan yaptığı işte uzmanlaşarak yükselir', 'Yönetici sayısı arttıkça verimlilik de artar', 'Terfi daima kıdeme göre verilmelidir'], 'Bir görevde başarılı olan kişi terfi ettirilir; yeni kademede yetersiz kalınca terfi durur. Sonuçta hiyerarşi, yetersiz kişilerle dolma eğilimi gösterir.'),
  ('Parkinson Yasası\'na göre bir iş için ayrılan süre ve kaynak ne yönde etkilenir?', 'İş, kendisine ayrılan sürenin tamamını dolduracak biçimde genişler', ['İş her zaman planlanandan önce biter', 'İş süresi ayrılan kaynaktan etkilenmez', 'Süre kısaldıkça işin kalitesi mutlaka artar'], 'C. Northcote Parkinson, işin tamamlanması için ayrılan zaman kadar uzayacağını söyler; bu, ofislerde zaman yönetimi uyarısı olarak anılır.'),
  ('Kaplan ve Norton\'un geliştirdiği dengeli başarı göstergesi kartı hangi dört bakış açısını birlikte değerlendirir?', 'Finansal, müşteri, iç süreçler, öğrenme ve gelişme', ['Üretim, pazarlama, finans, insan kaynakları', 'Güçlü yön, zayıf yön, fırsat, tehdit', 'Ürün, fiyat, dağıtım, tutundurma'], 'Dengeli başarı göstergesi kartı, yalnızca finansal ölçütlerle yetinmeyip dört boyutta performans ölçerek stratejiyi eyleme çevirmeyi amaçlar.'),
  ('Fordizm ile Toyotizm karşılaştırıldığında, aşağıdakilerden hangisi Toyotizm\'e özgü bir anlayıştır?', 'Talebe göre üretim ve hat çalışanlarının hata durdurma yetkisi', ['Standart tek ürünün stoklanmak üzere kitlesel üretimi', 'İşin tamamen basit ve tekrarlı parçalara bölünmesi', 'Montaj hattının sürekli hızından ödün verilmemesi'], 'Toyotizm, esnek ve talebe duyarlı üretimi, çalışana sorun çıkınca hattı durdurma yetkisini ve sürekli iyileştirmeyi öne çıkarır. Fordizm ise standart ürünün kitlesel üretimine dayanır.'),
  ('Bir yöneticinin doğrudan denetleyebileceği çalışan sayısına ilişkin \'kontrol alanı\' ilkesi bu sayı arttıkça hangi sonucu doğurur?', 'Denetimin güçleşmesi, ancak kademe sayısının azalması', ['Kademe sayısının artması ve denetimin kolaylaşması', 'Merkezî karar alma sürecinin hızlanması', 'Çalışan özerkliğinin her zaman azalması'], 'Geniş kontrol alanı örgütü yatay kılar ve kademeleri azaltır, ama yönetici başına düşen çalışan arttığı için sıkı denetim güçleşir.'),
  ('Fonksiyonel örgüt yapısının en önemli avantajı aşağıdakilerden hangisidir?', 'Aynı alandaki uzmanların bir arada çalışarak uzmanlık derinliği kazanması', ['Bölümler arası koordinasyonun kendiliğinden kolay olması', 'Ürün bazında sorumluluğun net olması', 'Müşteri değişimine çok hızlı uyum sağlaması'], 'Fonksiyonel yapıda benzer uzmanlıklar bir araya toplanır; bu, derinlemesine beceri sağlar, ancak bölümler arası koordinasyon zorlaşabilir.'),
  ('Resmî olarak belirlenmiş yetki zincirinin dışında, işin yürütülmesinde danışmanlık yapan ve karar yetkisi olmayan birimlere ne ad verilir?', 'Kurmay (danışman) birimler', ['Çizgi (hat) birimler', 'Matris birimler', 'Taşra birimleri'], 'Çizgi birimler doğrudan amaca hizmet eden emir-komuta zincirindedir; kurmay birimler ise çizgiye uzmanlık desteği sağlar ve genellikle emir verme yetkisi taşımaz.'),
  ('Yönetici yetkisinin devri (delegasyon) sırasında aşağıdakilerden hangisi devredilemez?', 'Sonuçlara ilişkin nihai sorumluluk', ['Görevin yapılması', 'İşi yapma yetkisi', 'Kaynak kullanma izni'], 'Yönetici görev ve yetkiyi astına devredebilir, ancak sonuçtan nihai olarak kendi üstüne karşı hesap vermeye devam eder.'),
  ('Bir şirkette \'Yüksek kademe karar verir, alt kademe uygular\' anlayışının ağır bastığı bir yapıda hangi sorun daha olası görülür?', 'Karar sürecinin yavaşlaması ve alt kademede inisiyatif eksikliği', ['Üst yönetimin sahadan daha çok bilgi alması', 'Çalışan bağlılığının çok artması', 'Kararların her zaman daha hızlı alınması'], 'Aşırı merkezîleşme, bilginin yukarı taşınmasını ve kararın aşağı inmesini gerektirir; bu da yavaşlık ve alt kademenin inisiyatiften uzaklaşması riskini doğurur.'),
  ('Bir yöneticinin yetki ve sorumluluğunun dengeli olması gerektiğini söyleyen ilke hangi yönetim anlayışının temel varsayımıdır?', 'Klasik yönetim yaklaşımı', ['Davranışsal yaklaşım', 'Sistem yaklaşımı', 'Nicel yaklaşım'], 'Klasik yaklaşım (Fayol, Taylor, Weber) örgütü resmî yapı, yetki-sorumluluk dengesi ve verim odaklı ilkelerle ele alır.'),
  ('Bir araştırmacı, hedef kitlenin tüm bireylerine eşit seçilme şansı vererek kura benzeri yöntemle örneklem seçiyor. Bu hangi örnekleme türüdür?', 'Basit tesadüfi örnekleme', ['Kota örneklemesi', 'Kolayda örnekleme', 'Yargısal örnekleme'], 'Basit tesadüfi örneklemede her birimin seçilme olasılığı eşittir; kota, kolayda ve yargısal yöntemler olasılığa dayanmayan örneklemelerdir.'),
  ('Bir marka, kafe önünden geçen ilk 100 kişiye anket uygulayarak müşteri görüşü topluyor. Bu örneklemenin başlıca sakıncası nedir?', 'Örneklemin hedef kitleyi temsil etmeme riski', ['Çok pahalı olması', 'Çok uzun sürmesi', 'İstatistik hata payının hesaplanabilir olması'], 'Kolayda örnekleme ulaşılması kolay kişilerle sınırlıdır ve seçilme olasılığı bilinmez; bu yüzden sonuçlar anakütleye genellenemeyebilir.'),
  ('Araştırmada \'geçerlilik\' kavramı neyi ifade eder?', 'Ölçme aracının ölçmek istediği şeyi gerçekten ölçmesini', ['Aynı ölçümün tekrarında aynı sonucun çıkmasını', 'Örneklemin çok büyük olmasını', 'Anketin kısa tutulmasını'], 'Geçerlilik doğru şeyi ölçmeyi, güvenirlik ise tutarlı ölçmeyi anlatır. Güvenilir bir ölçüm geçerli olmayabilir.'),
  ('Müşterilerin \'bir arkadaşınıza bu markayı tavsiye etme olasılığınız nedir?\' sorusuna 0-10 arası verdiği puanlarla ölçülen gösterge hangisidir?', 'Net Tavsiye Skoru', ['Müşteri edinme maliyeti', 'Pazar payı', 'Stok devir hızı'], 'NPS\'te 9-10 verenler destekçi, 0-6 verenler eleştirmen sayılır; destekçi yüzdesinden eleştirmen yüzdesi çıkarılarak hesaplanır.'),
  ('Bir firmanın NPS hesabında yanıtların %60\'ı 9-10, %30\'u 7-8, %10\'u 0-6 ise skor kaçtır?', '50', ['30', '60', '70'], 'NPS = destekçi yüzdesi − eleştirmen yüzdesi = 60 − 10 = 50; 7-8 verenler pasif sayılır ve hesaba katılmaz.'),
  ('Pahalı bir ürün aldıktan sonra \'Doğru seçim yaptım mı?\' diye huzursuzluk duyan tüketici hangi durumu yaşıyordur?', 'Bilişsel uyumsuzluk', ['Seçici algılama', 'Marka sadakati', 'Fiyat körlüğü'], 'Festinger\'in bilişsel uyumsuzluk kavramı, kararla çelişen düşünceler arasında kalmanın yarattığı rahatsızlığı anlatır; satış sonrası destek bunu azaltabilir.'),
  ('Aynı reklamı gören iki kişiden birinin yalnızca kendi görüşüne uyan kısımları hatırlaması hangi kavramla açıklanır?', 'Seçici algılama', ['Bilişsel uyumsuzluk', 'Güdüleme', 'Öğrenme eğrisi'], 'Seçici algılama, bireyin kendi inanç ve beklentileriyle örtüşen mesajları daha fazla fark edip hatırlaması eğilimidir.'),
  ('Yeni bir yazılımı ilk günden denemek isteyen ve riskleri göze alan küçük tüketici kitlesine Rogers\'ın yayılma modelinde ne ad verilir?', 'Yenilikçiler', ['Erken çoğunluk', 'Geç çoğunluk', 'Gelenekçiler'], 'Rogers\'a göre benimseyenler yenilikçiler, erken benimseyenler, erken çoğunluk, geç çoğunluk ve gecikenler olarak sınıflanır; yenilikçiler yaklaşık %2,5\'lik ilk gruptur.'),
  ('Rogers\'ın yenilik yayılımı modelinde \'erken benimseyenler\' kitlesinin pazardaki rolü nedir?', 'Fikir önderi olarak sonraki kitleleri etkilemeleri', ['Ürünü en son denemeleri', 'Yalnızca fiyat indirimiyle satın almaları', 'Ürünü geliştiren ekip içinde yer almaları'], 'Erken benimseyenler çevrelerince saygı gören fikir önderleridir; onların benimsemesi erken çoğunluğu harekete geçirir.'),
  ('Yüksek gelirli bir tüketici, sağlıklı beslenmeye verdiği önem nedeniyle organik ürün alıyor. Bu seçimi açıklayan etken hangisidir?', 'Yaşam tarzı ve değerler', ['Kuşak etkisi', 'Stok durumu', 'Dağıtım kanalı uzunluğu'], 'Yaşam tarzı, kişinin faaliyetleri, ilgileri ve görüşlerinin oluşturduğu bütündür; satın alma tercihlerini doğrudan etkileyen kişisel etkenlerdendir.'),
  ('Bir pazarlama araştırmasında aynı kişilerin aylar boyunca düzenli aralıklarla izlenerek tutumlarındaki değişimin ölçülmesi hangi araştırma türüdür?', 'Boylamsal (panel) araştırma', ['Kesitsel araştırma', 'Keşfedici nitel araştırma', 'Gözlem dışı deney'], 'Panel araştırmada aynı denekler zaman içinde tekrar ölçülür ve değişimler izlenir; kesitsel araştırmada ise ölçüm tek bir zamanda yapılır.'),
  ('Gerileme evresindeki bir ürün için firmanın izleyebileceği \'hasat\' stratejisi ne anlama gelir?', 'Pazarlama harcamalarını kısarak ürünün kalan nakit akışından yararlanma', ['Ürüne ek reklam bütçesi ayırıp pazar payını artırma', 'Ürünü yeniden tasarlayıp tanıtım evresine döndürme', 'Rakip firmayı satın alarak üretimi iki katına çıkarma'], 'Hasat stratejisinde yatırım ve harcamalar azaltılır; ürün, mevcut müşteri kitlesinden mümkün olduğunca nakit üretmeye devam ettirilir.'),
  ('Tek bir marka adı altında çok farklı ürünleri (ör. giyim, kozmetik ve mobilya) satan firmanın başlıca riski nedir?', 'Bir üründeki olumsuz deneyimin tüm markaya yansıması', ['Reklam giderlerinin çok artması', 'Her ürüne ayrı marka kimliği kurmanın zorunlu olması', 'Tüketicilerin markayı hiç hatırlamaması'], 'Aile markası stratejisinde marka itibarı ortaktır; bir üründeki kalite sorunu diğer ürünlere de zarar verebilir.'),
  ('Yeni ürün geliştirme sürecinde fikir üretiminden sonra ve ürün geliştirmeden önce yapılan \'iş analizi\' aşamasında ne değerlendirilir?', 'Tahmini satış, maliyet ve kârlılık', ['Ürünün ambalaj rengi', 'Dağıtım noktalarının adresleri', 'Çalışanların performans puanları'], 'İş analizinde fikrin satış potansiyeli, maliyetleri ve kâr beklentisi hesaplanır; yeterince çekici bulunan fikir ürün geliştirme aşamasına geçer.'),
  ('Bir ürünün sınırlı bir bölgede gerçek satış koşullarında denenmesi olan \'test pazarlaması\', yeni ürün sürecinde hangi amaca hizmet eder?', 'Ülke çapında lansmandan önce tüketici tepkisini ve pazarlama programını sınamak', ['Ürünün patentini almak', 'Üretimi tamamen durdurmak', 'Rakip ürünlerin fiyatını düşürmek'], 'Test pazarlaması, tam ölçekli yatırımdan önce ürünün ve pazarlama karmasının gerçek koşullarda nasıl çalıştığını görmeyi sağlar.'),
  ('Bir ürün hattına, mevcut ürünlerden daha pahalı ve prestijli bir model eklenmesi hangi hat stratejisidir?', 'Yukarı doğru hat genişletme', ['Aşağı doğru hat genişletme', 'Hat daraltma', 'Hat budama'], 'Hattın üst ucuna premium model eklemek yukarı genişlemedir; markanın imajını yükseltebilir ama mevcut müşteri kitlesini zorlayabilir.'),
  ('Ürün karmasının \'genişliği\' neyi ifade eder?', 'İşletmenin sunduğu farklı ürün hattı sayısını', ['Her hattaki ürün çeşidi sayısını', 'Ürünlerin ortalama satış fiyatını', 'Ürünlerin dağıtıldığı kanal sayısını'], 'Ürün karması genişliği hat sayısını, derinliği hattaki çeşit sayısını, uzunluğu toplam ürün sayısını gösterir.'),
  ('Bir sabun firmasının ürün karmasında 3 hat (sabun, şampuan, diş macunu) ve her hatta 4\'er ürün varsa karmanın uzunluğu kaçtır?', '12', ['3', '4', '7'], 'Ürün karması uzunluğu toplam ürün sayısıdır: 3 hat × 4 ürün = 12. Genişlik 3\'tür, hat uzunluğu ise 4\'tür.'),
  ('Markanın zihinde çağrıştırdığı karakter özelliklerinin \'dürüst\', \'maceracı\', \'sofistike\' gibi insani sıfatlarla tanımlanması hangi kavramla ilgilidir?', 'Marka kişiliği', ['Marka bilinirliği', 'Marka genişletme', 'Marka koruma'], 'Jennifer Aaker\'in marka kişiliği çalışması, markaların insan karakteri gibi sıfatlarla algılandığını ve bunun tüketiciyle duygusal bağ kurduğunu gösterir.'),
  ('Bir markanın başka bir markayla ortak ürün çıkarması (ör. bir spor markasıyla bir teknoloji firmasının işbirliği) hangi uygulamadır?', 'Ortak markalama', ['Marka genişletme', 'Özel markalı üretim', 'Marka konumlandırma'], 'Ortak markalamada iki marka birbirinin itibarından ve müşteri kitlesinden yararlanmak için tek ürün ya da kampanyada birleşir.'),
  ('Markanın tescil edilmeden kullanılması durumunda hangi sorun ortaya çıkabilir?', 'Başkasının markayı tescil ettirmesi hâlinde kullanma hakkının kaybedilmesi riski', ['Markanın otomatik olarak dünya çapında korunması', 'Markanın vergiden muaf olması', 'Markanın bilançoda varlık olarak gösterilmesi zorunluluğu'], 'Marka hakkı tescille doğar; tescilsiz kullanan taraf, adı önce tescil ettiren kişi karşısında zor durumda kalabilir.'),
  ('Bir lüks saat markasının ürününü bölgesinde yalnızca tek bir yetkili bayinin satmasına izin vermesi hangi dağıtım stratejisidir?', 'Münhasır (ayrıcalıklı) dağıtım', ['Yoğun dağıtım; ürünü mümkün olan her noktada bulundurma', 'Seçici dağıtım; birkaç uygun satıcıyla çalışma', 'Çoklu kanal dağıtımı; hem mağaza hem internet kullanma'], 'Münhasır dağıtım, prestij ve hizmet kontrolü gereken ürünlerde tek bayiye bölge hakkı vermekle işler; mağaza imajı markayla bütünleşir.'),
  ('Seçici dağıtım stratejisi hangi iki uç strateji arasında yer alır?', 'Yoğun dağıtım ile münhasır dağıtım', ['Doğrudan satış ile toptan satış', 'Fiyat kırma ile prestij fiyatlama', 'Tek marka ile çoklu marka'], 'Seçici dağıtımda ürün, belirli ölçütleri sağlayan sınırlı sayıda satıcıda bulunur; bu hem erişim hem kontrol arasında denge kurar.'),
  ('Üreticinin ürününü tek aracı olarak perakendeciye satması, perakendecinin de tüketiciye ulaştırması hangi kanal uzunluğudur?', 'Bir kademeli kanal', ['Sıfır kademeli (doğrudan) kanal, çünkü hiç aracı yoktur', 'İki kademeli kanal, çünkü iki aracı vardır', 'Üç kademeli kanal, çünkü komisyoncu da vardır'], 'Üretici-perakendeci-tüketici zincirinde tek aracı bulunur. Toptancı da eklenseydi iki kademeli kanal olurdu.'),
  ('Toptancı ve perakendecinin dağıtım zincirindeki asıl ekonomik katkısı nedir?', 'Temas ve işlem sayısını azaltarak dağıtım maliyetini ve çabasını düşürmesi', ['Ürünün üretim teknolojisini geliştirmesi', 'Ürünün patentini tescil ettirmesi', 'Tüketici vergilerini toplaması'], 'Aracılar, üretici ile çok sayıda tüketici arasındaki doğrudan temas sayısını azaltır; ayrıca stok, nakliye, finansman ve bilgi işlevlerini üstlenir.'),
  ('Kanal çatışmasının \'yatay\' türü hangi durumda ortaya çıkar?', 'Aynı kanal düzeyindeki iki bayinin birbirinin müşterisini çekmeye çalışması', ['Üreticinin bayiyle fiyat konusunda anlaşmazlığa düşmesi', 'Üreticinin kendi internet sitesinden satış yapıp bayisine rekabet etmesi', 'Toptancının perakendeciyi atlayıp tüketiciye satması'], 'Yatay çatışma aynı düzeydeki üyeler (iki bayi ya da iki perakendeci) arasında, dikey çatışma ise farklı düzeydeki üyeler (üretici-bayi) arasındadır.'),
  ('Bir üreticinin, bayilerine rakip olmak pahasına internet üzerinden doğrudan satışa başlaması hangi tür kanal çatışmasına yol açar?', 'Dikey kanal çatışması', ['Yatay kanal çatışması', 'Fiyat esnekliği çatışması', 'Kurumsal kimlik çatışması'], 'Aynı kanalın farklı düzeyindeki üyeler (üretici ile bayi) arasındaki çıkar çatışması dikey çatışmadır.'),
  ('İtme (push) stratejisinde pazarlama çabası öncelikle kime yönelir?', 'Dağıtım kanalındaki aracılara; aracıların ürünü tüketiciye itmesi hedeflenir', ['Doğrudan nihai tüketiciye; tüketicinin aracılardan ürünü istemesi hedeflenir', 'Rakip firmalara; fiyat savaşı başlatılması hedeflenir', 'Devlete; teşvik kredisi alınması hedeflenir'], 'İtme stratejisinde kişisel satış ve ticari indirimlerle aracılar ürünü almaya ve satmaya yöneltilir. Çekme stratejisinde ise reklam tüketicide talep yaratır.'),
  ('Bir ilaç firmasının, reçeteli ilaçlar için doktorlara ücretsiz numune ve ziyaretçi göndermesi hangi stratejinin tipik örneğidir?', 'Kişisel satışa dayalı itme stratejisi', ['Tüketiciye dönük çekme stratejisi', 'Marka genişletme stratejisi', 'Kaymak alma stratejisi'], 'Reçeteli ilaçta reklam kısıtlı olduğundan firma, ürünü yönlendiren doktorlara kişisel satışla ulaşır; bu itme yaklaşımıdır.'),
  ('Tüketicide ürün talebi yaratıp talebin perakendecileri ve toptancıları geri yönde \'çekmesini\' hedefleyen stratejide en çok hangi araç öne çıkar?', 'Medya reklamı', ['Kasa önü ürün yerleştirme', 'Bayi satış primleri', 'Ticari kredi ve vade indirimi'], 'Çekme stratejisi, nihai tüketiciye yönelik reklam ve tanıtımla talep oluşturur; tüketicinin istemesi perakendeciyi ve toptancıyı ürünü bulundurmaya zorlar.'),
  ('Tüketici adına hazırlanmış kişiselleştirilmiş e-posta veya mektuplarla müşteriden doğrudan yanıt almayı hedefleyen iletişime ne ad verilir?', 'Doğrudan pazarlama', ['Kitle reklamcılığı', 'Sponsorluk', 'Halkla ilişkiler'], 'Doğrudan pazarlama, medya aracısız biçimde bireysel müşteriyle iletişim kurup ölçülebilir yanıt (sipariş, tıklama) elde etmeye çalışır.'),
  ('Bir markanın sosyal medyada eğitici blog yazıları ve videolarla potansiyel müşterilerin ilgisini çekmesi hangi yaklaşımdır?', 'İçerik pazarlaması', ['Zorla pazarlama', 'Telefonla satış', 'Satış geliştirme'], 'İçerik pazarlaması, doğrudan satış söylemi yerine değerli bilgi ve eğlence sunarak hedef kitleyi markaya çekmeyi amaçlar.'),
  ('Etkili bir pazar bölümlendirmesinin ölçütlerinden \'erişilebilirlik\' ne anlama gelir?', 'Bölümün etkin biçimde ulaşılıp hizmet verilebilir olması', ['Bölümün çok kalabalık olması ve rakibin bulunmaması', 'Bölümün gelirinin sabit kalması ve vergi vermesi', 'Bölümdeki bireylerin birbirine benzemeyen davranışlar göstermesi'], 'Bir bölümün anlamlı olması için ölçülebilir, yeterince büyük, erişilebilir, ayırt edilebilir ve eyleme geçirilebilir olması gerekir.'),
  ('Ries ve Trout\'un konumlandırma yaklaşımına göre konumlandırma ürünün üzerinde mi yoksa zihinde mi gerçekleşir?', 'Hedef tüketicinin zihninde', ['Ürünün fiziksel yapısında, çünkü konumlandırma bir mühendislik işidir', 'Dağıtım kanalının raf düzeninde, çünkü konum rafla belirlenir', 'Muhasebe kayıtlarında, çünkü konum maliyetle belirlenir'], 'Ries ve Trout\'a göre konumlandırma ürüne yapılan bir şey değil, tüketicinin zihninde yapılan bir şeydir; aşırı bilgi ortamında sade bir algı yaratmayı amaçlar.'),
  ('Tüketicilerin markaları fiyat ve kalite gibi iki boyutta nasıl algıladığını gösteren ve rakipler arasındaki boşlukların bulunmasına yarayan grafiğe ne ad verilir?', 'Algı haritası', ['Gantt şeması', 'Karar ağacı', 'Başabaş grafiği'], 'Algı haritası, markaların tüketici zihnindeki konumlarını iki ya da daha fazla boyutta gösterir ve konumlandırmada boş alan bulmaya yardımcı olur.'),
  ('Satıcı fatura koşulunu \'2/10 net 30\' olarak belirtmiştir. 10.000 TL\'lik faturayı 8. günde ödeyen alıcı kaç TL öder?', '9.800', ['9.900', '9.980', '10.000'], '10 gün içinde ödeme yapana %2 indirim uygulanır: 10.000 × 0,98 = 9.800 TL. Fatura vadesi toplam 30 gündür.'),
  ('Bir mağazanın bazı ürünleri maliyetinin altında satıp müşteriyi mağazaya çekmeyi amaçlaması hangi uygulamadır?', 'Zarar lideri fiyatlama', ['Kaymak fiyatlama', 'Prestij fiyatlama', 'Esnek fiyatlama'], 'Zarar liderinde birkaç ürün cazip fiyatla sunulur; müşterinin mağazada başka ürünler de satın alacağı beklentisiyle toplam kâr artırılmaya çalışılır.'),
  ('Ürünün fiyatı yüksek olunca kalitesinin de yüksek olduğunu varsayan tüketici hangi psikolojik fiyat algısını yaşamaktadır?', 'Fiyat-kalite çağrışımı', ['Fiyat körlüğü', 'Referans fiyat etkisi', 'Tek fiyat uygulaması'], 'Kalitesi önceden değerlendirilemeyen ürünlerde tüketici fiyatı kalite göstergesi sayar; prestij fiyatlamanın temel dayanağıdır.'),
  ('Bir mağazanın, bir ürünü \'eski fiyat 400 TL, şimdi 299 TL\' biçiminde sunması hangi psikolojik etkiyi kullanır?', 'Referans fiyat etkisi', ['Sosyal kanıt etkisi', 'Sıkıntı etkisi', 'Kıtlık etkisi'], 'Yüksek \'eski\' fiyat bir referans noktası oluşturur; müşteri yeni fiyatı bu noktaya göre değerlendirir ve indirimi daha çekici bulur.'),
  ('Aynı ürünün farklı müşteri gruplarına (öğrenci, emekli, genel) farklı fiyattan satılması ekonomide hangi uygulamayla ilişkilidir?', 'Fiyat ayrımcılığı', ['Dampingle', 'Kartel anlaşması', 'Marka genişletme'], 'Satıcı, grupların farklı ödeme isteklerinden yararlanarak aynı ürünü farklı fiyata satar; pazarlamada bu, segment bazlı fiyatlandırma olarak uygulanır.'),
  ('Tüketici talebinin çok esnek olmadığı bir pazarda maliyet artışı yaşayan ve fiyatı yükseltebilen firmanın bu gücü hangi kavramla anılır?', 'Fiyat belirleme gücü', ['Ölçek ekonomisi', 'Güvenlik marjı', 'Ters kanal'], 'Talep esnekliği düşük ürünlerde ve güçlü markalarda firma fiyatı artırdığında satış miktarı az düşer; bu fiyat belirleme gücüdür.'),
  ('Hizmetlerin \'soyutluk\' özelliği pazarlamacıya hangi ek görevi yükler?', 'Fiziksel kanıt ve ipuçlarıyla hizmetin kalitesini görünür kılmak', ['Hizmeti depolayıp daha sonra satmak', 'Hizmeti patent koruması altında üretmek', 'Hizmeti yalnızca toptancı aracılığıyla dağıtmak'], 'Tüketici hizmeti satın almadan önce göremez ya da dokunamaz; bu nedenle ofis düzeni, sertifika ve referanslar gibi fiziksel kanıtlar güveni artırır.'),
  ('Hizmetin sunan kişiden ayrı düşünülememesi ve üretim ile tüketimin eşzamanlı olması hangi hizmet özelliğidir?', 'Üretim ve tüketimin ayrılamazlığı', ['Dayanıksızlık, çünkü hizmet stoklanamaz', 'Değişkenlik, çünkü kalite her seferinde farklıdır', 'Soyutluk, çünkü hizmet dokunulamaz'], 'Kuaförde saç kesilirken müşteri sürece katılır; hizmet verilirken tüketilir ve verenle ayrılamaz.'),
  ('Aynı bankanın iki şubesinde müşteriye sunulan hizmet kalitesinin farklı olması hizmetlerin hangi özelliğiyle açıklanır?', 'Değişkenlik', ['Soyutluk', 'Dayanıksızlık', 'Ayrılamazlık'], 'Hizmet kalitesi, onu sunan kişiye, yere ve zamana bağlı olarak değiştiği için standartlaştırması zordur.'),
  ('Boş kalan otel odasının geliri bir gün sonra telafi edilemez. Bu durum hizmetlerin hangi özelliğine örnektir?', 'Dayanıksızlık', ['Soyutluk; hizmetin dokunulamaz olması', 'Değişkenlik; hizmetin her seferinde farklı olması', 'Ayrılamazlık; hizmetin üreticiden bağımsız olması'], 'Hizmetler üretildiği anda tüketilmediğinde yok olur; bu yüzden talep dalgalanmalarını yönetmek (fiyat, rezervasyon) hizmet pazarlamasının sorunudur.'),
  ('Hizmet kalitesini ölçen SERVQUAL modelinde \'güvenirlik\' boyutu neyi ifade eder?', 'Vaat edilen hizmeti güvenilir ve doğru biçimde yerine getirebilme', ['Çalışanların güler yüzlü olması', 'Mekânın modern görünmesi', 'Müşteriye özel ilgi gösterilmesi'], 'SERVQUAL boyutları güvenirlik, duyarlılık, güvence, empati ve fiziksel kanıtlardır; güvenirlik, sözün tutulmasıyla ilgilidir.'),
  ('Bir çevrim içi reklamın 50.000 kez gösterilip 750 kez tıklanması durumunda tıklama oranı (CTR) yüzde kaçtır?', '1,5', ['0,75', '15', '6,7'], 'CTR = tıklama / gösterim = 750 / 50.000 = %1,5.'),
  ('Bir dijital reklam kampanyasında harcama 6.000 TL, elde edilen satış geliri 24.000 TL ise reklam getirisi (ROAS) kaçtır?', '4', ['0,25', '18', '30'], 'ROAS = reklam geliri / reklam harcaması = 24.000 / 6.000 = 4; harcanan her liraya karşılık 4 lira gelir elde edilmiştir.'),
  ('Müşterinin web sitesine bıraktığı ürünleri sepetten satın almadan terk etmesi (sepet terki) hakkında hangi önlem en mantıklıdır?', 'Hatırlatma e-postası ve ödeme adımlarını sadeleştirme', ['Fiyatı iki katına çıkarma', 'Sitenin tüm sayfalarını kapatma', 'Ürün çeşitlerini tek modele indirme'], 'Sepet terkinin nedenleri çoğunlukla ek maliyet, karmaşık ödeme ya da dikkat dağınıklığıdır; hatırlatma ve basit ödeme dönüşümü artırır.'),
  ('İşletmeden işletmeye (B2B) pazarlamada karar süreci, tüketici pazarlamasına göre genellikle nasıl işler?', 'Daha uzun sürer, birden çok kişinin katıldığı resmî bir satın alma birimince yürütülür', ['Anlık duygusal tercihlerle tek kişi tarafından hızla verilir', 'Yalnızca fiyat etiketine bakılarak yapılır', 'Reklamdan sonra hemen sipariş verilir'], 'Kurumsal alımlar teknik şartname, birden çok onay ve sözleşme gerektirdiğinden süre uzar; türetilmiş talep yapısı da pazarlamayı farklılaştırır.'),
  ('Yeşil pazarlamada \'yeşil badana\' (greenwashing) uygulaması nedir?', 'Çevreye duyarlı olmadığı hâlde çevre dostu görünmek için yanıltıcı iddialarda bulunmak', ['Çevreye zarar vermemek için üretimi durdurmak', 'Bitki satan mağaza açmak', 'Çevre dostu paketlemeyi vergi indirimiyle desteklemek'], 'Greenwashing, firmanın gerçek çevresel performansı yetersizken pazarlama iletişimiyle sürdürülebilir görünmesidir; tüketici güvenini zedeler.'),
  ('Yapılandırılmış mülakat, yapılandırılmamış mülakata göre hangi bakımdan üstündür?', 'Tüm adaylara aynı sorular sorulduğu için karşılaştırma ve geçerlilik daha yüksektir', ['Adayın kişisel hayatını daha fazla sorgulama imkânı tanır', 'Sürenin çok kısa olmasını sağlar', 'Mülakat yapanın sezgisine daha çok yer verir'], 'Aynı soruların aynı sırada sorulması adaylar arasında adil kıyas sağlar ve mülakatçı yanlılığını azaltarak geçerliliği artırır.'),
  ('Adayların grup tartışması, sunum ve rol yapma gibi uygulamalarla bir gün boyunca gözlenerek değerlendirildiği seçme yöntemi hangisidir?', 'Değerlendirme merkezi', ['Referans araştırması', 'Yazılı bilgi testi', 'Telefonla ön görüşme'], 'Değerlendirme merkezlerinde aday davranışı birden çok simülasyonla ve çok sayıda gözlemci tarafından değerlendirilir; yöneticilik adaylarında yaygındır.'),
  ('Mülakatçının adayın tek bir olumlu özelliğinden etkilenip diğer özelliklerini de yüksek değerlendirmesine ne ad verilir?', 'Hâle etkisi', ['Merkezî eğilim hatası', 'Yakınlık (son olay) hatası', 'Pygmalion etkisi'], 'Hâle etkisi (halo effect), bir özelliğin genel yargıyı çarpıtmasıdır; performans değerlendirmesinde ve işe alımda sık görülen bir hatadır.'),
  ('Performans değerlendirmesinde yönetici bütün çalışanlara ortalama puan veriyorsa hangi hata yapılmaktadır?', 'Merkezî eğilim hatası', ['Cömertlik hatası; tüm çalışanlara yüksek puan verilir', 'Katılık hatası; tüm çalışanlara düşük puan verilir', 'Yakınlık hatası; yalnızca son olay hatırlanır'], 'Merkezî eğilim hatasında değerlendirici uç puanlardan kaçınıp herkesi orta düzeyde gösterir; böylece iyi ve kötü performans ayırt edilemez.'),
  ('Yılın tümünü değil, yalnızca son iki ayda yaşanan olayları esas alarak performans notu veren yönetici hangi hatayı yapmaktadır?', 'Yakınlık (son olay) hatası', ['Hâle etkisi', 'Cömertlik hatası', 'Benzerlik hatası'], 'Son dönemde olanlar hafızada daha taze olduğundan değerlendirme eğilimlidir; yıl boyu kayıt tutmak bu hatayı azaltır.'),
  ('Eğitim programlarının etkinliğini değerlendiren Kirkpatrick modelinin ilk basamağı hangisidir?', 'Tepki', ['Öğrenme', 'Davranış', 'Sonuç'], 'Kirkpatrick modeli tepki, öğrenme, davranış ve sonuç basamaklarından oluşur; tepki, katılımcıların eğitimi nasıl bulduğunu ölçer.'),
  ('Kirkpatrick modelinde, eğitimde öğrenilenlerin iş yerindeki gerçek uygulamaya aktarılıp aktarılmadığı hangi basamakta değerlendirilir?', 'Davranış', ['Tepki', 'Öğrenme', 'Sonuç'], 'Davranış basamağı, öğrenilenlerin işe aktarılıp aktarılmadığını ölçer; sonuç basamağı ise kâr, kalite ve verimlilik gibi örgütsel çıktıları kapsar.'),
  ('Bir çalışanın bir üst kadroya hazırlanması için aday havuzunun önceden belirlenip geliştirildiği uygulamaya ne denir?', 'Halefiyet (yedek yetiştirme) planlaması', ['Performans primi planlaması', 'Stok kontrol planlaması', 'Bütçe revizyonu'], 'Halefiyet planlaması kritik kadrolarda ani boşluk riskine karşı içeriden aday yetiştirmeyi amaçlar.'),
  ('İşlerin zorluk, sorumluluk ve gerekli nitelik açısından değerlendirilip ücret kademelerine yerleştirilmesine ne ad verilir?', 'İş değerleme', ['Performans değerleme', 'İş analizi', 'Stok değerleme'], 'İş değerleme, işlerin göreli değerini belirleyerek adil ve tutarlı bir ücret yapısı kurmayı amaçlar; sıralama, sınıflandırma, puanlama ve faktör karşılaştırma yöntemleri vardır.'),
  ('İş değerlemede her iş için ayrı ayrı faktör puanları verilip toplam puana göre ücret grubu belirlenen yöntem hangisidir?', 'Puanlama yöntemi', ['Sıralama yöntemi', 'Sınıflandırma yöntemi', 'Ankara yöntemi'], 'Puanlama yönteminde bilgi, sorumluluk, çaba ve çalışma koşulu gibi faktörlere puan verilir; toplam puan işin ücret düzeyini belirler.'),
  ('Çalışanın görevini tam olarak yapmasını engelleyen, yani rolünün beklentileri hakkında net olmaması durumuna ne ad verilir?', 'Rol belirsizliği', ['Rol çatışması', 'İş zenginleştirme', 'Yetki devri'], 'Rol belirsizliğinde kişi ne beklendiğini bilmez; rol çatışmasında ise birbiriyle uyuşmayan iki beklentiyle karşı karşıya kalır.'),
  ('Bir bisküvi firmasının tamamen ilgisiz bir sektör olan inşaata yatırım yapması hangi çeşitlendirme türüdür?', 'Konglomera (ilgisiz) çeşitlendirme', ['İlgili çeşitlendirme; mevcut yetkinliklerle ilişkili alana girme', 'Geriye dikey bütünleşme; tedarikçiyi satın alma', 'Pazar geliştirme; mevcut ürünü yeni bölgeye satma'], 'İlgisiz çeşitlendirmede yeni iş kolu ile mevcut ürün, teknoloji ya da pazar arasında bağ yoktur; risk yayılır ama yönetim zorluğu artar.'),
  ('Şirketin büyümesi yerine bazı iş birimlerini kapatıp satarak daha küçük ve odaklı hâle gelmesini amaçlayan strateji hangisidir?', 'Küçülme (daralma) stratejisi', ['Pazar nüfuzu stratejisi; mevcut pazardaki payı artırma', 'Ürün geliştirme stratejisi; yeni model sunma', 'İleriye dikey bütünleşme stratejisi; dağıtımı satın alma'], 'Küçülme stratejisinde zayıf birimler elden çıkarılır, maliyetler azaltılır ve kaynaklar çekirdek faaliyetlere toplanır.'),
  ('Kurumsal (şirket) düzeyi strateji ile iş birimi düzeyi stratejiyi ayıran temel soru hangisidir?', 'Hangi sektörlerde yer alacağımıza karşı, nasıl rekabet edeceğimize', ['Hangi çalışana ne kadar ücret ödeneceğine karşı, ne zaman terfi verileceğine', 'Hangi muhasebe yönteminin seçileceğine karşı, hangi vergi dilimine girileceğine', 'Hangi ürünün hangi renkte üretileceğine karşı, ambalajın nasıl katlanacağına'], 'Kurumsal strateji portföy ve sektör seçimiyle ilgilidir; iş birimi stratejisi bir sektörde rekabet üstünlüğü kurmakla; fonksiyonel strateji ise bunların işlevsel uygulamasıyla ilgilidir.'),
  ('Clayton Christensen\'in \'yıkıcı yenilik\' kavramı en iyi hangi duruma uyar?', 'Basit ve ucuz başlayan yeniliğin zamanla lider firmaları geride bırakması', ['Lider firmanın mevcut ürününü yıllarca iyileştirip premium müşterilerinin beklentisini daha iyi karşılaması', 'Devletin sektörde fiyat sınırı koyması', 'Firmanın ürününü yalnızca premium segmentte satması'], 'Yıkıcı yenilik önce göz ardı edilen basit ve ucuz çözümlerle başlar, zamanla ana akım müşterinin ihtiyaçlarını karşılayarak yerleşik firmaları tehdit eder.'),
  ('Değişken ve belirsiz bir gelecekte birbirinden farklı birkaç olası durumu önceden tasarlayıp stratejiyi bunlara göre sınayan yönteme ne denir?', 'Senaryo planlaması', ['Başabaş noktası analizi', 'Pareto analizi', 'Benchmarking'], 'Senaryo planlaması tek bir tahmin yerine birden çok olası gelecek kurgusu geliştirir; belirsizlik yüksekken esnek karar almaya yardım eder.'),
  ('Stratejik ittifak ile birleşme-devralma arasındaki temel fark nedir?', 'Taraflar bağımsızlığını koruyarak belirli alanda işbirliği yapar', ['İttifakta bir şirket tamamen satın alınarak ortadan kalkar', 'İttifakta şirketlerin sermayesi birleşip yeni tek bir tüzel kişilik doğar', 'İttifak yalnızca devlet kurumları arasında yapılır'], 'Stratejik ittifakta taraflar ayrı tüzel kişilikler olarak kalır; birleşme ya da devralmada ise mülkiyet ve yönetim el değiştirir.'),
  ('Deneyim (öğrenme) eğrisi etkisine göre kümülatif üretim miktarı iki katına çıktıkça birim maliyet nasıl değişir?', 'Belirli oranda azalır', ['Aynı oranda artar', 'Hiç değişmeden sabit kalır', 'Sıfıra eşit olur'], 'Boston Consulting Group\'un deneyim eğrisi, birikmiş deneyim arttıkça birim maliyetin sistematik biçimde düştüğünü öne sürer.'),
  ('Bir stratejinin uygulanmasında \'stratejik kontrol\' aşamasının görevi nedir?', 'Sonuçları izleyip gerekirse stratejiyi gözden geçirmek', ['Misyon bildirimini baştan yazıp tüm örgüt yapısını yeniden kurmak', 'İşletmenin tüm çalışanlarını değiştirmek', 'Rakiplerin ürünlerini taklit etmek'], 'Strateji formülasyon, uygulama ve kontrol döngüsünde kontrol aşaması, sapmaları ve çevre değişikliklerini izleyerek düzeltici adımı tetikler.'),
  ('Net kâr marjı %5, varlık devir hızı 2, özkaynak çarpanı 3 olan bir işletmenin özkaynak kârlılığı yüzde kaçtır?', '30', ['10', '15', '60'], 'DuPont ayrıştırmasına göre ROE = 0,05 × 2 × 3 = 0,30, yani %30.'),
  ('Alacak tahsil süresi 40 gün, stok bekleme süresi 60 gün, borç ödeme süresi 30 gün olan işletmenin nakit dönüşüm döngüsü kaç gündür?', '70', ['130', '100', '10'], 'Nakit dönüşüm döngüsü = stok süresi + alacak süresi − borç süresi = 60 + 40 − 30 = 70 gün.'),
  ('Bir işletmenin nakit dönüşüm döngüsünü kısaltmasının işletme sermayesi ihtiyacına etkisi ne olur?', 'İşletme sermayesi ihtiyacı azalır', ['İşletme sermayesi ihtiyacı artar, çünkü nakit daha uzun süre bağlı kalır', 'Etkisi olmaz, çünkü döngü yalnızca muhasebe kaydıdır', 'Borçlar otomatik olarak artar, çünkü tedarikçiler peşin ister'], 'Parayı mala, alacağa dönüştürüp geri alma süresi kısaldıkça işletmenin bağladığı kaynak azalır ve dışarıdan finansman ihtiyacı düşer.'),
  ('Bir işletmenin makineyi satın almak yerine belirli bir kira bedeliyle uzun süre kullanıp dönem sonunda mülkiyeti alma hakkı elde etmesine ne denir?', 'Finansal kiralama', ['Faktoring ya da forfaiting', 'Halka arz', 'Hisse geri alımı'], 'Finansal kiralamada makine kiracı tarafından kullanılır, sözleşme sonunda düşük bedelle satın alma opsiyonu bulunabilir; böylece yüksek ilk yatırım yükünden kaçınılır.'),
  ('Katkı payı oranı %40 olan bir işletmenin aylık sabit giderleri 120.000 TL ise başabaş satış tutarı kaç TL\'dir?', '300.000', ['48.000', '120.000', '480.000'], 'Başabaş satış tutarı = sabit gider / katkı payı oranı = 120.000 / 0,40 = 300.000 TL.'),
  ('Satışlardaki küçük bir artışın faaliyet kârında çok daha büyük yüzde artışa yol açması, sabit gider oranı yüksek işletmelerde hangi kavramla açıklanır?', 'İşletme kaldıracı', ['Finansal kaldıraç etkisi', 'Ölçek ekonomisi', 'Güvenlik marjı'], 'Sabit maliyetlerin payı yüksekse satış arttığında kâr daha hızlı artar, düşüşte ise daha hızlı erir; bu durum faaliyet kaldıracı etkisidir.'),
  ('Borçla finansman kullanan bir işletmede faiz giderlerinin vergiden düşülebilir olması sermaye maliyetini nasıl etkiler?', 'Borcun vergi sonrası maliyetini düşürür', ['Borcun maliyetini yükseltir, çünkü faizler azalır', 'Özkaynak maliyetini sıfırlar, çünkü ortaklar vergi öder', 'Etkisi yoktur, çünkü faiz gider yazılamaz'], 'Faiz gideri vergi matrahını azalttığı için borcun vergi sonrası maliyeti, faiz oranı × (1 − vergi oranı) kadardır; bu da borçlanmayı cazip kılar.'),
  ('Bir şirket kârının büyük kısmını temettü yerine yeni yatırımlara ayırıyorsa hangi kâr dağıtım yaklaşımını benimsemiştir?', 'Kârı büyük ölçüde işletmede tutma', ['Yüksek ve sabit temettü ödeme politikası uygulama', 'Hisse bölünmesi yoluyla hisse sayısını çoğaltma', 'Kârın tamamını ortaklara nakit olarak dağıtma'], 'Hızlı büyüyen firmalar kârı yatırımda kullanmayı tercih eder; temettü beklentisi olan yatırımcılar ise olgun firmaları seçer.'),
  ('Ticari kredi (tedarikçi kredisi) işletme için hangi bakımdan önemli bir finansman kaynağıdır?', 'Vadeli alımla ek maliyetsiz nakit ihtiyacını erteler', ['Bankaya yatırılan mevduatın hiç faiz ödememesini sağlar ve vergi doğurur', 'Hisse senedi çıkarılarak halka açık kaynak yaratılmasını sağlar', 'Devletin işletmenin vergi borcunu tamamen silmesini sağlar'], 'Tedarikçinin vadeli satışı, nakit ödemeyi ileri tarihe atar; peşin ödeme iskontosu kaçırılırsa kredinin örtük maliyeti yüksek olabilir.'),
  ('Toyota üretim sisteminde tanımlanan yedi israf türünden biri olarak \'gereğinden fazla üretim\' neden en tehlikeli israf sayılır?', 'Diğer israfları (stok, bekleme, taşıma) da doğurduğu için', ['Çalışan sayısını doğrudan sıfıra indirdiği için ve işçilik maliyetini artırdığı için', 'Müşterinin siparişini iptal etmesine neden olduğu için ve ürünün garanti kapsamını bozduğu için', 'Yalnızca nakliye sigortasını pahalılaştırdığı için ve tedarikçileri değiştirdiği için'], 'Taiichi Ohno\'ya göre aşırı üretim stok, taşıma, depolama ve bekleme gibi diğer israfların kaynağıdır; bu nedenle \'israfların anası\' sayılır.'),
  ('Goldratt\'ın kısıtlar teorisine göre bir üretim hattının toplam çıktısını ne belirler?', 'En yavaş çalışan kaynak', ['En hızlı çalışan makine, çünkü çıktı onun hızına bağlıdır', 'Yönetim kademelerinin sayısı, çünkü kararlar yavaşlar', 'Çalışanların ortalama yaşı, çünkü deneyim hızı belirler'], 'Zincir en zayıf halkası kadar güçlüdür; kısıtlar teorisi önce darboğazı bulur, sonra onu sürekli verimli kullanmayı ve gevşetmeyi önerir.'),
  ('Malzeme ihtiyaç planlaması (MRP) bir ürün için hangi bilgilere dayanarak hangi çıktıyı verir?', 'Üretim programı, ürün ağacı ve stoktan sipariş zamanlarını', ['Müşteri memnuniyet anketine dayanarak yeni reklam bütçesini ve kampanya takvimini', 'Yıllık bilançoya dayanarak ortaklara dağıtılacak temettü oranını ve ödeme tarihini', 'Rakip fiyatlara dayanarak ürünün satış fiyatını ve indirim dönemlerini'], 'MRP, ana üretim programından başlayarak ürün ağacı ve eldeki stoku kullanıp bileşenlerin sipariş ve üretim zamanlarını hesaplar.'),
  ('Ürün yerleşimi (hat tipi yerleşim) hangi durumda tercih edilir?', 'Standart ürün yüksek hacimle üretildiğinde', ['Her sipariş farklı olduğunda ve işlem sırası sık değiştiğinde', 'Hacim çok düşük, ürün tekil ve sıra belirsiz olduğunda', 'Yalnızca hizmet işletmelerinde ve depolarda'], 'Hat tipi yerleşimde makineler işlem sırasına göre dizilir; yüksek hacimde akış verimlidir. Atölye tipi yerleşim ise çeşitliliği yüksek işlere uygundur.'),
  ('Bir istatistiksel süreç kontrol (SPC) grafiğinde ölçüm noktalarının üst kontrol sınırının dışına çıkması neyi gösterir?', 'Süreç kontrol dışına çıkmış olabilir', ['Süreç mükemmel çalışıyor ve hiç müdahale gerekmiyor', 'Müşteri memnuniyeti beklenenden fazla artmış durumda', 'Stoklar yetersiz ve sipariş verilmesi gerekiyor'], 'Kontrol sınırlarının dışına çıkan noktalar rastlantı dışı bir neden (makine ayarı, malzeme) olduğunu düşündürür ve inceleme gerektirir.'),
  ('Bir ürünün tasarım aşamasında hedef satış fiyatından istenen kâr çıkarılarak izin verilen maliyetin belirlenmesine ne ad verilir?', 'Hedef maliyetleme', ['Standart maliyetleme', 'Tam maliyetleme', 'Sipariş maliyetleme'], 'Hedef maliyetlemede fiyat pazar tarafından verilir; izin verilen maliyet = hedef fiyat − hedef kâr olarak bulunur ve ürün buna göre tasarlanır.'),
  ('Takt süresi, üretimde neyi ifade eder?', 'Talebi karşılamak için bir birimin üretim sıklığı', ['Makinenin bir çevrimi tamamlaması için gereken süre ve hız', 'Çalışanın günlük mola ve dinlenme süresi', 'Hammaddenin depoda bekleyeceği azami süre'], 'Takt süresi = kullanılabilir üretim süresi / müşteri talebi; üretim hızının talebe eşitlenmesini sağlar.'),
  ('Laplace (yetersiz neden) ölçütünde karar verici belirsizlik altında hangi varsayımı yapar?', 'Doğal durumların tümünün eşit olasılıklı olduğunu', ['En kötü durumun kesin yaşanacağını ve diğerlerinin olmayacağını', 'En iyi durumun kesin yaşanacağını ve diğerlerinin olmayacağını', 'Olasılıkların hiçbir zaman bilinemeyeceğini ve hesaba katılamayacağını'], 'Laplace ölçütü, olasılıklar bilinmediğinde durumlara eşit olasılık verip her seçeneğin ortalama getirisini karşılaştırır.'),
  ('Programlanmış (rutin) karar ile programlanmamış karar arasındaki fark nedir?', 'Rutin kural işler, yeni durum ayrı yargı gerektirir', ['Programlanmış kararlar yalnızca üst yönetimce, programlanmamışlar yalnızca alt kademece alınır', 'Programlanmış kararlar daima daha pahalıdır; programlanmamış kararlar ise bedavadır', 'Programlanmış karar bilgisayarla, programlanmamış karar telefonla alınır'], 'Rutin işlerde (stok siparişi, bordro) hazır kurallar uygulanır; yeni ve belirsiz sorunlar (yeni pazara girmek) yargı ve yaratıcılık gerektirir.'),
  ('Eisenhower matrisinde hem \'acil\' hem \'önemli\' olan işler için en uygun eylem hangisidir?', 'Hemen yapmak', ['Başkasına devretmek ve takip etmek', 'Takvime koyup ileri tarihte yapmak', 'Tamamen ortadan kaldırıp yapmamak'], 'Eisenhower matrisi işleri acil-önemli eksenlerinde dörde ayırır: acil ve önemli hemen yapılır; önemli ama acil olmayan planlanır; acil ama önemsiz devredilir; ikisi de olmayan elenir.'),
  ('İletişim sürecindeki \'gürültü\' kavramı neyi anlatır?', 'Mesajın anlaşılmasını bozan engel', ['Mesajın yazılı hazırlanması durumu ve resmî dil', 'Mesajın yalnızca yüksek sesle iletilmesi ve tekrarı', 'Mesajın alıcıya hiç ulaşmaması hâli ve kaybolması'], 'Gürültü, yalnızca fiziksel ses değil; dil farkı, ön yargı, dikkat dağınıklığı gibi iletişimi bozan her etkendir.'),
  ('Mehrabian\'ın iletişim araştırmasında duygu ve tutumun iletilmesinde sözsüz öğelerin ağırlıklı olması neyi hatırlatır?', 'Beden dili ve ses tonu da söz kadar önemlidir', ['Yazılı iletişim sözlü iletişimden daha güvenilirdir ve tercih edilmelidir', 'Sözcüklerin tamamen önemsiz olup etkisi bulunmadığını gösterir', 'Resmî iletişimin hiç kullanılmaması gerektiğini ve yasaklanmasını gösterir'], 'Mehrabian\'ın bulguları duygusal mesajlarda sözcük dışı işaretlerin etkisini vurgular; tutarsız mesajlarda alıcı genellikle sözsüz ipuçlarına inanır.'),
  ('Schein\'ın örgüt kültürü modelinde ofis düzeni, giyim kuralı ve şirket logosu hangi düzeyde yer alır?', 'Görünür eserler', ['Benimsenen değerler ve normlar', 'Temel varsayımlar ve inançlar', 'Kâr hedefleri ve bütçeler'], 'Yüzeyde gözlenebilen düzen, tören, mimari ve semboller \'eserler\' düzeyidir; değerler ve varsayımlar daha derinde yer alır.'),
  ('Örgütsel gelişim (OD) çalışmalarının temel amacı aşağıdakilerden hangisidir?', 'Etkinlik ve iyilik hâlini planlı geliştirmek', ['Çalışan sayısını her yıl düzenli biçimde azaltmak ve küçülmek', 'Yalnızca üretim maliyetini sıfırlamak ve giderleri kısmak', 'Örgütün tüm kararlarını tek kişiye devredip merkezileştirmek'], 'OD, davranış bilimi bilgisiyle örgüt kültürünü, ilişkileri ve süreçleri planlı biçimde geliştirmeyi hedefleyen uzun vadeli bir değişim çabasıdır.'),
  ('Karar vermede \'sınırlı rasyonellik\' varsayımı yöneticilerin neyi yapabileceğini söyler?', 'Tatmin edici çözümü seçecekleri', ['Daima en iyi çözümü bulup uygulayacakları', 'Karar vermekten tamamen vazgeçecekleri ve ertelemeyi seçecekleri', 'Yalnızca sezgiyle karar vereceklerini ve veriye bakmayacakları'], 'Herbert Simon\'a göre bilgi ve zaman sınırlı olduğundan karar vericiler optimum yerine yeterince iyi bulunan ilk çözümü seçer.'),
  ('Grup karar vermenin bireysel karar vermeye göre başlıca dezavantajı aşağıdakilerden hangisidir?', 'Yavaşlama ve grup düşüncesi', ['Daha az bilgi toplanması ve tek bakış açısı', 'Karar kabulünün azalması ve sahiplenmenin düşmesi', 'Çözümlerin her zaman daha az yaratıcı çıkması'], 'Gruplar daha çok bilgi ve bakış açısı sağlar, ancak zaman alır ve uyum baskısı grup düşüncesine yol açabilir.'),
  ('Aynı projede (A 3 gün, B 2 gün, C 4 gün, D 1 gün; B ve C paralel) B işinin toplam bolluk (gecikme payı) süresi kaç gündür?', '2', ['12', '4', '6'], 'Kritik yol A-C-D 8 gündür; B yolu 6 gündür. B işi projeyi geciktirmeden 8 − 6 = 2 gün gecikebilir.'),
  ('Şelale (waterfall) yaklaşımı ile çevik (agile) yaklaşımı karşılaştırıldığında hangisi çevik yaklaşıma özgüdür?', 'Kısa döngülerde ürün teslimi ve sık geri bildirim', ['Tüm gereksinimlerin başta dondurulması', 'Aşamaların tek yönde ilerlemesi', 'Tek bir büyük teslimat ve en sonda yapılan toplu test aşaması'], 'Çevik yaklaşım ürünü küçük artımlarla geliştirir ve müşteri geri bildirimiyle yönünü sürekli ayarlar; şelalede aşamalar ardışık ve sabit ilerler.'),
  ('Kanban panosunda \'devam eden iş sınırı\' (WIP limit) konmasının temel amacı nedir?', 'Aynı anda çok iş başlatmayı önlemek', ['Çalışan sayısını azaltarak ekibi küçültmek', 'Toplantı sayısını artırmak', 'İşleri rastgele sıralamak'], 'WIP sınırı darboğazları görünür kılar ve işlerin başlamak yerine bitirilmesini teşvik eder; akış süresini kısaltır.'),
  ('Proje yöneticisinin bir riski sigorta yaptırarak üçüncü tarafa aktarması hangi risk yanıtıdır?', 'Riski transfer etme', ['Riskten kaçınma yoluna gitme', 'Riski bilinçli olarak kabullenme', 'Riski izleme listesine alma'], 'Sigorta ya da sözleşmeyle riskin sonuçlarının başka tarafa devredilmesi transferdir; kaçınma ise riskli faaliyetten vazgeçmektir.'),
  ('Bir proje yöneticisi, riskli bir tedarikçiyi hiç kullanmayıp başka bir tedarikçiye geçiyor. Bu hangi risk yanıtıdır?', 'Riskten kaçınma', ['Riski transfer etme', 'Riski kabullenme', 'Riski izleme'], 'Riskin kaynağını ortadan kaldıran karar (tedarikçiyi değiştirmek) kaçınma yanıtıdır.'),
  ('Bir proje 100 günlük planlanmış ve %40\'ı tamamlandığında planlanan bütçenin %50\'i harcanmışsa maliyet yönünden durum nedir?', 'Maliyet aşımı vardır', ['Bütçe altındadır', 'Tam planlandığı gibidir', 'Maliyet verisi yoktur'], 'Tamamlanan iş değeri bütçenin %40\'ı iken harcama %50\'dir; harcanan para yapılan işten fazla olduğundan maliyet aşımı söz konusudur.'),
  ('Yüksek-düşük yöntemiyle bir maliyetin sabit ve değişken kısımları ayrılırken hangi dönemler esas alınır?', 'En yüksek ve en düşük faaliyet dönemleri', ['En yüksek ve en düşük kâr yapılan iki mali dönem', 'En eski ve en yeni kayıtlı iki yıllık mali dönem', 'İlk çeyrek ile son çeyrek mali dönemleri'], 'Yöntem, iki uç faaliyet düzeyindeki maliyet farkını faaliyet farkına bölerek birim değişken maliyeti bulur, kalanı sabit maliyet sayar.'),
  ('Bir işletme özel bir siparişi, boş kapasitesi varken değişken maliyetinin üzerinde bir fiyattan kabul ederse katkı payı ne olur?', 'Pozitif katkı sağlar ve kârı artırır', ['Zarara sebep olur ve sabit maliyeti yükseltir', 'Sabit giderleri sıfırlar', 'Kârı mutlaka düşürür'], 'Sabit maliyet zaten katlanılmış olduğundan, değişken maliyeti aşan her fiyat sabit giderlere ve kâra katkı yapar.'),
  ('Hedef kâra göre bütçe yapan işletme, satış bütçesinden sonra genellikle hangi bütçeyi hazırlar?', 'Üretim bütçesi', ['Nakit bütçesi, çünkü nakit hep ilk sıradadır', 'Bilanço bütçesi, çünkü bilanço satıştan önce yapılır', 'Vergi bütçesi, çünkü vergi hesaplanmadan satış olmaz'], 'Ana bütçede satış tahmini temel alınır; buna göre stok hedefini de içeren üretim bütçesi, ardından girdi, işçilik ve genel gider bütçeleri hazırlanır.'),
  ('Ürünü ucuz ve her yerde bulunabilir kılmanın yeterli olduğunu varsayan, talebin arzdan fazla olduğu dönemlere özgü işletme anlayışı hangisidir?', 'Üretim anlayışı', ['Satış anlayışı; ürünün agresif tutundurmayla satılması gerektiği düşüncesi', 'Pazarlama anlayışı; müşteri ihtiyaçlarının merkeze alınması gerektiği düşüncesi', 'Toplumsal pazarlama anlayışı; toplumun uzun vadeli refahının gözetilmesi'], 'Üretim anlayışında tüketicinin ucuz ve kolay bulunan ürünü seçeceği varsayılır; odak verimlilik ve dağıtım genişliğidir. Talep arzı aştığında bu yaklaşım geçerlidir.'),
  ('Üretim kapasitesi talebi aşınca firmaların \'üretileni satmak\' için yoğun reklam ve satış baskısına yöneldiği işletme anlayışı hangisidir?', 'Satış anlayışı', ['Üretim anlayışı; verimlilik ve geniş dağıtıma odaklanan yaklaşım', 'Ürün anlayışı; yalnızca kaliteli ürünün kendini satacağı varsayımı', 'İlişki pazarlaması; uzun dönemli müşteri bağlılığına odaklanan yaklaşım'], 'Satış anlayışında tüketicinin kendiliğinden yeterince almayacağı düşünülür; ikna, reklam ve satış çabası öne çıkar. Müşteri memnuniyeti ikinci plandadır.'),
  ('Theodore Levitt\'in \'Pazarlama Miyopisi\' makalesi firmalara hangi hatadan kaçınmayı öğütler?', 'İşi müşteri ihtiyacı üzerinden tanımlamamak', ['Ürün kalitesinin rakiplerden daha yüksek tutulması gerektiğini söylemek', 'Aşırı çok müşteri araştırması yaparak zaman kaybetmek ve pahalı veri toplamak', 'Aşırı çeşitlilikle ürün hattı kurmaktan'], 'Levitt\'e göre demiryolları kendilerini \'ulaşım\' işinde değil \'demiryolu\' işinde gördükleri için gerilediler; iş, ürün değil müşteri ihtiyacı üzerinden tanımlanmalıdır.'),
  ('Lauterborn\'un 4C modeli, 4P karmasının her unsurunu müşteri açısından yeniden adlandırır. \'Fiyat\' unsurunun karşılığı hangisidir?', 'Müşterinin katlandığı maliyet', ['Müşteriye sunulan ürün çözümü ve fayda paketi', 'Mağazaya ulaşma rahatlığı ve kolaylık düzeyi', 'Karşılıklı iletişim ve diyalog kurma düzeyi'], '4C modeli ürünü müşteri çözümü, fiyatı müşteri maliyeti, dağıtımı rahatlık, tutundurmayı iletişim olarak yorumlar.'),
  ('Bir markanın her satın alınan ürün karşılığında bir çocuğun okul eğitimine bağış yapacağını duyurması hangi pazarlama uygulamasıdır?', 'Sosyal amaçlı (kampanya) pazarlama', ['Karşılaştırmalı reklam; rakiple kıyaslama yapma', 'Zarar lideri fiyatlama; maliyetin altında satma', 'Doğrudan pazarlama; kişiselleştirilmiş posta'], 'Sosyal amaçlı pazarlamada satışın belirli bir kısmı sosyal bir amaca aktarılır; marka hem toplumsal fayda yaratır hem de itibar ve satış kazanır.'),
  ('Deneyimsel pazarlamada markanın hedeflediği şey aşağıdakilerden hangisidir?', 'Duyusal ve duygusal deneyim yaşatmak', ['Yalnızca ürünün fiyat avantajını rakamlarla anlatmak ve kıyaslamak', 'Müşteri verisini hiç toplamayıp rastgele davranmak ve ilgilenmemek', 'Satışı yalnızca aracılara yaptırmak'], 'Deneyimsel pazarlama, ürünün özelliklerinden çok müşterinin markayla yaşadığı duyusal, duygusal ve sosyal deneyime odaklanır.'),
  ('Nöropazarlama araştırmalarında tüketici tepkisini ölçmek için hangi tür araçlar kullanılır?', 'Beyin görüntüleme ve göz izleme ölçümleri', ['Yalnızca açık uçlu yazılı anketler ve görüşme formları', 'Yalnızca satış faturaları ve kasa fişi kayıtları', 'Yalnızca mağaza kira sözleşmeleri ve kâr zarar tabloları'], 'Nöropazarlama, tüketicinin bilinçli olarak ifade edemediği tepkileri beyin aktivitesi, göz hareketi ve kalp atışı gibi ölçümlerle inceler.'),
  ('İşletmenin pazarlama faaliyetlerinin sistemli ve düzenli biçimde dış çevre, hedef ve stratejiler bakımından değerlendirilmesine ne ad verilir?', 'Pazarlama denetimi', ['Muhasebe denetimi ve finansal tablo incelemesi', 'Vergi denetimi ve beyan kontrolü incelemesi', 'Stok sayımı ve envanter döküm çalışması'], 'Pazarlama denetimi, firmanın pazarlama ortamını, hedeflerini, stratejilerini ve faaliyetlerini kapsamlı, bağımsız ve periyodik olarak inceler.'),
  ('Bir yeni ürünün ilk yılda ulaşabileceği toplam talebin üst sınırını (bütün potansiyel alıcıların ihtiyacını) anlatan kavram hangisidir?', 'Pazar potansiyeli', ['Pazar payı, yani firmanın gerçek satış oranı', 'Satış tahmini, yani firmanın beklediği satış hacmi', 'Müşteri sadakati, yani tekrar satın alma eğilimi'], 'Pazar potansiyeli, belirli koşullarda bir ürüne yönelik azami toplam talebi; satış tahmini ise firmanın gerçekçi beklediği satış miktarını ifade eder.'),
  ('Bir marka satışlarının %30\'unu mevcut müşterilerden elde ediyor. Bu durumda marka hangi konuda güçlü demektir?', 'Müşteri sadakati ve tekrar alım', ['Yeni müşteri bulmakta rakiplerden belirgin biçimde daha iyi olması', 'Dağıtımda yalnızca tek kanal kullanması ve aracıyı yok sayması', 'Fiyatlarda daima sektörün en ucuzu olması ve kâr marjı yaratması'], 'Satışların önemli kısmının mevcut müşterilerden gelmesi, tekrar satın alma ve sadakate işaret eder; yeni müşteri edinme gücü bu veriden çıkarılamaz.'),
  ('Bir satıcının müşteriye hâlihazırda aldığı ürünün daha üst modelini önermesi hangi satış tekniğidir?', 'Yukarı satış', ['Çapraz satış; tamamlayıcı başka bir ürünün önerilmesi', 'Zarar lideri satış; maliyet altı fiyatla müşteri çekilmesi', 'Yeniden konumlandırma; ürünün imajının değiştirilmesi'], 'Yukarı satışta aynı ürünün daha pahalı ve gelişmiş sürümü sunulur; çapraz satışta ise tamamlayıcı ürün (ör. telefona kılıf) önerilir.'),
  ('Satış elemanlarının performansını değerlendirirken yalnızca ciro yerine satış kotası gerçekleşme oranının kullanılması neyi sağlar?', 'Farklı bölge potansiyellerindeki elemanları adil kıyaslar', ['Satışların kendiliğinden artmasını sağlar ve vergi yükünü hafifletir ve ucuzlatır', 'Müşteri şikâyetlerinin hiç olmamasını ve iadelerin sıfırlanmasını sağlar ve garantiler', 'Ürün kalitesinin otomatik olarak yükselmesini sağlar ve maliyeti kendiliğinden düşürür'], 'Her bölgenin potansiyeli farklıdır; hedefe göre gerçekleşme oranı, düşük potansiyelli bölgedeki çabayı da adil biçimde yansıtır.'),
  ('Mağaza atmosferinde müzik, koku ve aydınlatmanın kullanılması hangi pazarlama anlayışının uzantısıdır?', 'Deneyimsel ve duyusal pazarlamanın', ['Zarar lideri fiyatlama uygulamasının ve kampanya gücünün', 'Hasat stratejisinin ve nakit akışı yönetiminin', 'Ters lojistik süreçlerinin ve iade yönetiminin ve maliyetinin'], 'Duyusal ipuçları, müşterinin mağazada kalma süresini ve duygusal tepkisini etkileyerek satın alma davranışını yönlendirir.'),
  ('Bir reklam kampanyası hedef kitlenin %50\'sine ulaşmış ve ulaşılanlara ortalama 4 kez gösterilmiştir. Toplam GRP kaçtır?', '200', ['54', '12,5', '46'], 'GRP = erişim yüzdesi × ortalama frekans = 50 × 4 = 200 puan.'),
  ('Bir reklamın 500.000 kişiye ulaşması için 25.000 TL harcanmıştır. Bin kişi başına maliyet (CPM) kaç TL\'dir?', '50', ['5', '0,05', '500'], 'CPM = maliyet / erişim × 1.000 = 25.000 / 500.000 × 1.000 = 50 TL.'),
  ('Hedef-görev yöntemiyle reklam bütçesi belirlerken ilk adım nedir?', 'İletişim hedefini tanımlamak', ['Geçen yılın bütçesine belirli bir yüzde eklemek ve onaylamak', 'Rakiplerin harcamasını aynen kopyalayıp bütçelemek ve uygulamak', 'Kasada kalan tüm parayı reklama harcayıp bütçeyi kapatmak'], 'Önce hedef (farkındalığı %60 yapmak gibi) belirlenir, sonra bu hedefe ulaşmak için gerekli görevler ve maliyetleri toplanarak bütçe oluşur; en rasyonel yöntemdir.'),
  ('Bir reklam mesajında \'sosyal kanıt\' ilkesine örnek hangisidir?', '\'Bir milyon kişi tercih etti\' ifadesi', ['\'Sadece bugün için %50 indirim\' ifadesi ve kampanyası', '\'Stokta son iki ürün kaldı\' ifadesi ve uyarısı', '\'Doktorlar da bu ürünü öneriyor\' ifadesi ve görüşü'], 'Sosyal kanıt, başkalarının davranışını doğru yol sayma eğilimidir; kalabalığın tercihi gösterilerek güven yaratılır. Diğer ifadeler sırasıyla indirim, kıtlık ve otorite etkisidir.'),
  ('Kalite maliyetlerinden \'önleme maliyeti\' aşağıdakilerden hangisidir?', 'Çalışanlara kalite eğitimi verilmesi', ['Müşteriye iade edilen ürünlerin yenisiyle değiştirilmesi', 'Üretim sonu tüm ürünlerin tek tek test edilmesi', 'Hatalı ürünlerin üretim hattında yeniden işlenmesi'], 'Önleme maliyeti hatayı baştan engellemek için yapılan harcamadır (eğitim, süreç tasarımı). Test değerleme, hurda ve yeniden işleme iç hata, iade ise dış hata maliyetidir.'),
  ('Hatalı ürünün müşteriye ulaştıktan sonra garanti kapsamında değiştirilmesi hangi kalite maliyeti türüne girer?', 'Dış hata maliyeti', ['Önleme maliyeti', 'Değerleme maliyeti', 'İç hata maliyeti'], 'Hata müşteriye ulaştıktan sonra ortaya çıkıyorsa dış hata maliyeti doğar; bu maliyet itibar kaybını da içerdiğinden en pahalı türdür.'),
  ('Kalite maliyetleri arasında \'hatanın en erken evrede yakalanması\' için yatırım yapmak neden daha ekonomiktir?', 'Hatanın maliyeti ilerleyen aşamalarda katlanarak arttığı için', ['Müşterilerin hatayı görmek istemediği ve iade ettiği için talebin düşmesi nedeniyle', 'Vergi mevzuatının önleme giderini zorunlu kılması nedeniyle', 'Makinelerin hata yapmasının imkânsız olması nedeniyle'], 'Bir hatanın düzeltme maliyeti tasarımdan üretime, oradan müşteriye doğru ilerledikçe birkaç kat artar; erken önlem bu yüzden ucuzdur.'),
  ('Tesis yeri seçiminde \'faktör puanlama\' yönteminde ne yapılır?', 'Ölçütler ağırlıklandırılıp alternatifler puanlanır', ['Yalnızca en ucuz arsa seçilir ve diğer ölçütlere bakılmaz hiç', 'Tüm seçenekler kura ile belirlenir ve sonuç hemen açıklanır sonra', 'Rakibin yeri aynen taklit edilir ve araştırma yapılmaz hiç'], 'Ölçütler (işgücü, pazar yakınlığı, ulaşım, vergi gibi) ağırlıklandırılır; her yer ağırlıklı puan toplamıyla sıralanarak seçilir.'),
  ('Tedarik zincirinde \'yalın\' strateji ile \'çevik\' strateji karşılaştırıldığında hangisi çeviğe özgüdür?', 'Esnek kapasite ve tampon bulundurmak', ['Maliyet düşürmek için stok ve bekleme süresini en aza indirmek ve yalın kalmak', 'Standart ürünleri öngörülebilir talebe göre toplu üretmek ve stoklamak ve satmak', 'Tedarikçi sayısını tek kaynağa indirip fiyat pazarlığı yapmak'], 'Yalın zincirler öngörülebilir talepte maliyet verimliliğini hedefler; çevik zincirler ise kısa ömürlü ve değişken talepte hız ve esnekliği öne çıkarır.'),
  ('Bir ürünün son dönem tahmini 100, gerçekleşen talep 120 ve alfa 0,3 ise üstel düzeltmeyle yeni tahmin kaçtır?', '106', ['110', '114', '120'], 'Yeni tahmin = 100 + 0,3 × (120 − 100) = 106.'),
  ('Doğrusal programlamada bir işletme iki ürünü üretiyor; kısıtları sağlayan alanda kârı enbüyükleyen çözüm genellikle nerede bulunur?', 'Uygun bölgenin köşe noktalarından birinde', ['Bölgenin tam ortasındaki noktada ve çevresinde', 'Bölgenin dışındaki herhangi bir noktada ve kenarında', 'Eksen üzerinde olmayan her noktada'], 'Doğrusal amaç fonksiyonunun optimumu, kısıtların oluşturduğu çokgenin bir köşe noktasında gerçekleşir; bu nedenle yalnızca köşeler denenir.'),
  ('Kuyruk sistemlerinde kullanım oranı 1\'in üzerine çıkarsa ne olur?', 'Kuyruk zamanla sınırsız büyür', ['Kuyruk kendiliğinden kısalır', 'Hizmet süresi sıfırlanır', 'Müşteri kaybı sona erer'], 'Varışlar hizmet kapasitesini aştığında bekleyen sayısı durmadan artar; sistem kararlı bir duruma gelemez.'),
  ('Şirket yöneticilerine hisse senedi opsiyonu verilmesi vekâlet sorununa karşı hangi amaca hizmet eder?', 'Yönetici ile hissedar çıkarını hizalamaya', ['Yöneticiyi her türlü vergiden muaf tutmaya', 'Ortaklık yapısını kamuoyundan gizlemeye çalışmaya', 'Üretim maliyetini sıfırlamaya'], 'Yönetici, hisse fiyatı arttıkça kazandığı için hissedarla aynı yönde güdülenir; böylece çıkar çatışması azalır.'),
  ('Dairesel ekonomi yaklaşımının temel ilkesi nedir?', 'Ürün ve malzemeyi uzun süre kullanıp yeniden değerlendirmek', ['Ürünü kısa sürede eskitip yenisini satmayı hedeflemek ve satışı artırmak', 'Hammaddeyi yalnızca bir kez kullanıp sonra atmak ve yenisini almak', 'Atığı doğrudan denize ve toprağa göndererek maliyeti düşürmek'], 'Doğrusal \'al-üret-at\' modelinin yerine onarım, yeniden kullanım ve geri dönüşümle malzeme döngüsünü kapatmayı hedefler.'),
  ('Planlı eskitme (planned obsolescence) uygulamasının tüketici ve çevre açısından eleştirilen yönü nedir?', 'Ürünün kasıtlı kısa ömürlü tasarlanması', ['Ürünün çok uzun ömürlü ve onarılabilir olması durumu hakkında', 'Fiyatların sürekli düşmesi ve tüketici gücünün artması durumu', 'Ürün çeşitliliğinin gittikçe azalıp tek modele inmesi durumu'], 'Planlı eskitme, ürünü yeniden satın alma ihtiyacı yaratmak için bilinçli kısa ömürlü yapmaktır; tüketici maliyetini ve atığı artırdığı için eleştirilir.'),
  ('Adil ticaret (fair trade) sertifikasının temel amacı nedir?', 'Üreticiye adil fiyat ve iyi çalışma koşulu', ['Ürünün gümrük vergisini tamamen sıfırlamak ve ithalatı serbest bırakmak', 'Rekabeti ortadan kaldırarak tek satıcılı pazar kurmak ve fiyatı sabitlemek', 'Reklam yapmayı tümüyle yasaklayıp tanıtımı kısıtlamak ve cezalandırmak'], 'Adil ticaret, özellikle gelişmekte olan ülkelerdeki küçük üreticilere asgari fiyat güvencesi ve toplumsal prim sağlayarak sürdürülebilir üretimi destekler.'),
  ('Kuruluşundan kısa süre sonra yurt dışı satışlara yönelen ve başından itibaren küresel pazarı hedefleyen girişimlere ne ad verilir?', 'Doğuştan küresel firmalar', ['Aile işletmeleri ve geleneksel işletmeler', 'Kamu iktisadi teşebbüsleri ve kamu kuruluşları', 'Kooperatifler ve yardımlaşma sandıkları'], 'İnternet ve düşük iletişim maliyetleri sayesinde bazı girişimler yerel büyümeyi beklemeden doğrudan uluslararası pazarlara yönelir.'),
  ('Ülke riski değerlendirmesinde \'siyasi risk\' aşağıdakilerden hangisidir?', 'Kamulaştırma ya da ani mevzuat değişikliğiyle yatırımın zarar görmesi olasılığı', ['Hammadde fiyatlarının mevsimsel dalgalanması, çünkü fiyat siyasetle belirlenir', 'Çalışanların izin kullanma oranı, çünkü yasal haktır', 'Reklam harcamalarının artması, çünkü siyaset reklamı etkiler'], 'Siyasi risk, hükümet kararları, siyasi istikrarsızlık, kamulaştırma ve savaş gibi yatırımı doğrudan etkileyen olayların olasılığıdır.'),
  ('Küresel pazarlamada \'küresel düşün, yerel hareket et\' (glokalizasyon) anlayışı ne öngörür?', 'Tutarlı küresel marka stratejisini yerel zevke göre uyarlamayı', ['Her ülkede tamamen farklı ve ilgisiz markalar kurmayı', 'Ürünleri hiçbir uyarlama yapmadan satmayı', 'Yalnızca iç pazarda satış yapmayı'], 'Glokalizasyon, marka kimliğini ve çekirdek değerleri korurken ürün, dil ve iletişimi yerel koşullara uygun hâle getirmektir.'),
  ('Bir ülkenin kur değişimi, yabancı yatırımcının o ülkeden elde ettiği kârın kendi para cinsinden değerini nasıl etkiler?', 'Yerel para değer kaybederse kâr yatırımcı parasıyla daha az eder', ['Yerel para değer kaybederse kâr yatırımcı parasıyla daha fazla eder', 'Kur hiçbir şekilde kârı etkilemez', 'Yalnızca vergi oranları kârı etkiler'], 'Yatırımcı kârını kendi parasına çevirirken yerel paranın değer kaybı çevrilen tutarı azaltır; bu \'kur riski\' olarak yönetilir.'),
  ('İhracatta \'dolaylı ihracat\' ile \'doğrudan ihracat\' arasındaki temel fark nedir?', 'Dolaylı ihracatta aracı bir dış ticaret şirketi kullanılır', ['Doğrudan ihracatta ürün hiç taşınmaz, çünkü satış yerinde yapılır', 'Dolaylı ihracatta mal ücretsiz verilir, çünkü aracı ödeme yapmaz', 'İkisi arasında hiçbir fark yoktur, çünkü sonuç aynıdır'], 'Dolaylı ihracatta üretici, ihracat işini ihracat şirketine ya da komisyoncuya bırakır; doğrudan ihracatta ise kendi dış satış birimiyle yabancı alıcıyla çalışır.'),
  ('Çokuluslu bir şirketin yeni bir pazarda lisans anlaşması yerine ortak girişimi seçmesi hangi avantajı sağlar?', 'Daha fazla kontrol ve kâr payı', ['Hiç yatırım gerektirmemesi, çünkü ortak sermaye koyar', 'Rakiplerin teknolojisini öğrenememesi, çünkü bilgi paylaşılmaz', 'Yerel mevzuattan tamamen muaf kalması, çünkü yerel ortak vardır'], 'Lisansta firma yalnızca royalti alır; ortak girişimde ise sermaye koyar ve kârdan pay alır, yönetim kararlarına katılır.'),
  ('Üretimin maliyet nedeniyle yurt dışına taşınmasının yerel işgücü piyasasına olası olumsuz etkisi nedir?', 'İlgili sektörlerde işten çıkarmalar ve işsizlik', ['Yerel ücretlerin hızla artması, çünkü işgücü azalır', 'Sendikaların bütünüyle ortadan kalkması', 'Yerel tüketimin sıfırlanması'], 'Üretim kaydırıldığında yurt içinde o alandaki istihdam azalır; ancak başka sektörlerde maliyet düşüşü ve ucuz mal etkisiyle yeni işler doğabilir.'),
  ('Bir ülkedeki firmanın yabancı müşterisine mal gönderdikten sonra ödemenin güvenceye alınması için bankanın ödeme garantisi vermesini sağlayan belge hangisidir?', 'Akreditif', ['Konşimento', 'Fatura', 'Gümrük beyannamesi'], 'Akreditifte alıcının bankası, satıcıya koşullar yerine getirildiğinde ödeme taahhüdünde bulunur; böylece alıcıya ve satıcıya güven sağlar.'),
  ('Uluslararası ticarette Incoterms kuralları neyi belirler?', 'Taraflar arasında taşıma, sigorta ve risk yükünün paylaşımını', ['Ülkelerin gümrük vergisi oranlarını, çünkü gümrük tarifesi budur', 'Şirketlerin vergi oranını, çünkü vergi sözleşmeleridir', 'İşçilerin asgari ücretini, çünkü uluslararası standarttır'], 'Incoterms, Uluslararası Ticaret Odası\'nın teslim şartlarını standartlaştıran kurallarıdır; maliyet ve riskin satıcıdan alıcıya geçtiği noktayı gösterir.'),
  ('Bir firmanın hem satış hem üretimi yurt dışında yaptığı, mülkiyetin tamamen kendisine ait olduğu giriş biçimi hangisidir?', 'Tam sahipli yan kuruluş', ['İhracat, çünkü satış yurt dışındadır', 'Lisans, çünkü üretim yurt dışındadır', 'Franchise, çünkü marka yurt dışındadır'], 'Tam sahipli yan kuruluşla firma tam kontrol sağlar, ancak en yüksek sermaye ve risk üstlenir.'),
  ('Bir e-ticaret sitesinde aynı ürünü gören müşteriye \'bunu alanlar şunu da aldı\' önerisi sunulması hangi analize dayanır?', 'Öneri sistemleri ve birliktelik analizi', ['Pareto analizi, çünkü %20\'lik müşteri bulunur', 'Kritik yol analizi, çünkü süre hesaplanır', 'Başabaş analizi, çünkü kâr sıfırlanır'], 'Öneri algoritmaları geçmiş birlikte satın alma örüntülerinden benzer ürünleri bulur; çapraz satışı ve sepet tutarını artırır.'),
  ('Müşterileri son alışveriş tarihi, alışveriş sıklığı ve harcama tutarına göre sınıflandıran RFM analizinde \'R\' neyi ifade eder?', 'Son alışverişten bu yana geçen süre', ['Müşterinin alışveriş sıklığı, çünkü tekrar önemlidir', 'Müşterinin toplam harcaması, çünkü para önemlidir', 'Müşterinin ürün iadesi, çünkü iade önemlidir'], 'RFM; recency (yenilik), frequency (sıklık) ve monetary (parasal değer) ölçütlerini birleştirerek müşteri segmentlerini belirler.'),
  ('Müşteri yolculuğu (customer journey) haritası hangi amaçla hazırlanır?', 'Müşterinin markayla temas noktalarını ve deneyimini aşama aşama görmek için', ['Çalışanların maaşını hesaplamak için', 'Gümrük vergisini belirlemek için', 'Fabrika yerleşimini çizmek için'], 'Yolculuk haritası, farkındalıktan satın alma sonrasına kadar müşterinin ne düşündüğünü, yaptığını ve hissettiğini temas noktalarıyla gösterir; sorunları ve fırsatları ortaya çıkarır.'),
  ('Bir blog yazarının, okurlarını ürün sayfasına yönlendirip satıştan komisyon alması hangi modelle ilgilidir?', 'Ortaklık (affiliate) pazarlaması', ['Doğrudan postalama, çünkü posta ile iletişim vardır', 'Sponsorluk, çünkü etkinlik desteklenir', 'Ürün yerleştirme, çünkü film sahnesi vardır'], 'Affiliate pazarlamada ortak satış getirdiğinde komisyon alır; böylece satıcı yalnızca sonuca ödeme yapar.'),
  ('Bir kullanıcı sitenizi ziyaret ettikten sonra başka sitelerde markanızın reklamını görüyorsa hangi teknik kullanılmıştır?', 'Yeniden hedefleme', ['Gerilla pazarlama, çünkü sürpriz etkisi vardır', 'Deneyimsel pazarlama, çünkü deneyim sunulur', 'Ağızdan ağıza pazarlama, çünkü kullanıcılar paylaşır'], 'Remarketing, siteyi ziyaret eden ancak satın almayanlara çerez ya da kimlik verisiyle yeniden reklam göstererek geri çağırmayı amaçlar.'),
  ('Kişisel verileri işleyen işletmelerin Türkiye\'de uyması gereken temel kanun hangisidir?', 'Kişisel Verilerin Korunması Kanunu', ['Türk Borçlar Kanunu, çünkü sözleşme esas alınır', 'Rekabetin Korunması Hakkında Kanun, çünkü rekabeti düzenler', 'Vergi Usul Kanunu, çünkü kayıtları düzenler'], '6698 sayılı KVKK, kişisel verilerin işlenmesinde açık rıza, aydınlatma ve güvenlik yükümlülüklerini düzenler.'),
  ('Bir mobil uygulamanın indirme sayısı yüksek olduğu hâlde günlük aktif kullanıcıları düşükse bu durum neyi gösterir?', 'Kullanıcı tutundurma ve elde tutma sorunu olduğunu', ['Uygulamanın çok başarılı olduğunu, çünkü indirme yeterlidir', 'Uygulamanın fiyatının sıfır olduğunu, çünkü bedavadır', 'Pazar payının %100 olduğunu, çünkü herkes indirmiştir'], 'İndirme tek başına başarı değildir; aktif kullanım ve elde tutma oranı, uygulamanın gerçek değerini ve gelir potansiyelini gösterir.'),
  ('Ohio Eyalet Üniversitesi liderlik çalışmalarında \'yapıyı başlatma\' boyutu liderin hangi davranışını anlatır?', 'Görev ve rolleri tanımlayıp işi örgütlemesini', ['Çalışanların duygularına özen göstermesini ve güven oluşturmasını', 'Kararları tamamen astlara bırakmasını ve izlemesini', 'Örgüt dışı kişilerle ilişki kurmasını ve tanıtım yapmasını'], 'Ohio çalışmalarında iki boyut vardır: yapıyı başlatma (işi tanımlama ve planlama) ve ilgi gösterme (çalışanlara saygı, güven ve destek).'),
  ('Michigan Üniversitesi liderlik çalışmalarına göre \'çalışan odaklı\' lider nasıl davranır?', 'İnsan ilişkilerine ve çalışan ihtiyaçlarına önem verir', ['Yalnızca üretim hedeflerini ve ölçülebilir çıktıları önemser', 'Kararları kendi başına alır ve astlara bilgi vermez', 'Kuralları katı biçimde uygulatıp denetimi sıklaştırır'], 'Michigan çalışmaları liderleri çalışan odaklı ve üretim odaklı olarak ayırır; çalışan odaklı liderler ilişkiye ve destek vermeye önem verir.'),
  ('Thomas-Kilmann çatışma yönetimi modelinde kendi çıkarını da karşı tarafın çıkarını da tam olarak karşılamaya çalışan tarz hangisidir?', 'İşbirliği', ['Rekabet; kendi isteğini dayatma', 'Uzlaşma; ortada buluşma', 'Kaçınma; sorundan uzak durma'], 'İşbirliği tarzı iki tarafın ihtiyaçlarını birlikte karşılayacak yeni bir çözüm arar; uzlaşma ise her iki tarafın da bir parça ödün vermesidir.'),
  ('Çatışma türlerinden \'görev çatışması\' neyi ifade eder?', 'İşin içeriği ve hedefleri konusundaki görüş ayrılıkları', ['Kişiler arası duygusal gerginlik ve antipati', 'Kimin hangi işi yapacağı konusundaki sorumluluk tartışması', 'Hiyerarşi içinde yetki talepleri'], 'Görev çatışması işin ne olduğu ve nasıl yapılacağı üzerine fikir ayrılığıdır; ölçülü düzeyde karar kalitesini artırabilir, ilişki çatışması ise çoğunlukla zararlıdır.'),
  ('Müzakerede \'BATNA\' terimi neyi ifade eder?', 'Anlaşmasızlıkta eldeki en iyi seçenek', ['Karşı tarafın müzakerede sunduğu ilk teklif tutarı ve koşulları', 'Anlaşmanın hukuki bağlayıcılığı ve süresi ile maddeleri', 'Müzakerenin yapılacağı tarih, saat ve yeri ile tutanağı'], 'BATNA (Best Alternative To a Negotiated Agreement), müzakere gücünü belirler: iyi alternatifi olan taraf kötü bir anlaşmayı reddedebilir.'),
  ('Çalışanın görev tanımında yer almadığı hâlde gönüllü olarak iş arkadaşlarına yardım etmesi hangi kavramla adlandırılır?', 'Örgütsel vatandaşlık davranışı', ['Rol çatışması yaşama durumu ve baskısı', 'Sosyal kaytarma yapma davranışı ve gizlenmesi', 'Pygmalion etkisi yaratma süreci ve sonucu'], 'Örgütsel vatandaşlık davranışı resmî ödül sisteminde karşılığı olmayan, örgüte katkı sağlayan gönüllü davranışlardır.'),
  ('Bandura\'nın öz yeterlik kavramı bireyin hangi inancını ifade eder?', 'İşi başarabileceğine dair kendine güveni', ['Başkalarının kendisini sevdiğine ve onayladığına dair inancını ve güvenini', 'Şirketin kendisini her koşulda koruyacağına dair inancını ve beklentisini', 'Kendi maaşının yeterli ve adil olduğuna dair inancını ve memnuniyetini'], 'Yüksek öz yeterlik, kişinin daha zor hedefler koymasına, daha çok çaba göstermesine ve engeller karşısında pes etmemesine yol açar.'),
  ('Rotter\'in denetim odağı kavramında \'içsel denetim odaklı\' kişi olayların nedenlerini nerede görür?', 'Kendi davranış ve çabalarında', ['Şans ve kader gibi dış güçlerde', 'Hükümetin kararlarında', 'Hava koşullarında'], 'İçsel denetim odaklı kişiler sonuçları kendi çabalarına bağlar; dışsal denetim odaklılar ise şans, kader ya da başkalarının gücüne bağlar.'),
  ('Büyük Beş kişilik özelliklerinden \'sorumluluk (vicdanlılık)\' yüksek olan çalışan hakkında hangisi beklenir?', 'Düzenli, planlı ve hedefe odaklı çalışma', ['Her zaman başkalarıyla çatışma', 'İşlerini sürekli ertelemek', 'Hiç risk almamak ve değişimi reddetmek'], 'Büyük Beş (açıklık, sorumluluk, dışa dönüklük, uyumluluk, duygusal denge) içinde sorumluluk, farklı işlerde iş performansını en tutarlı öngören özelliktir.'),
  ('Aynı tür sorunlar tekrar ettiğinde uygulanmak üzere önceden belirlenmiş, adım adım uygulama sırası içeren sürekli plana ne ad verilir?', 'Prosedür', ['Politika, çünkü genel karar çerçevesidir', 'Program, çünkü tek seferlik iş takvimidir', 'Proje, çünkü sonu belli bir çalışmadır'], 'Politika karar vermeye yön verir, prosedür işlerin hangi sırayla yapılacağını gösterir, kural ise yapılması ya da yapılmaması gerekenleri açıkça belirtir.'),
  ('Bir işletmenin \'çalışanların hepsi iş yerinde kimlik kartı takmak zorundadır\' hükmü hangi sürekli plan türüdür?', 'Kural', ['Politika', 'Prosedür', 'Program'], 'Kural, esneklik tanımayan ve açık bir davranış zorunluluğu getiren plan türüdür; politika ise karar verici için yönlendirici bir çerçeve sunar.'),
  ('Denetimin \'ileri besleme\' (önleyici) türü ne zaman yapılır?', 'Faaliyet başlamadan önce olası sorunları önlemek için', ['Faaliyet sürerken anlık düzeltme için', 'Faaliyet bittikten sonra sonuçları değerlendirmek için', 'Yalnızca yıl sonunda vergi için'], 'Önleyici denetim girdileri (malzeme, eğitim, bütçe) baştan kontrol ederek hatanın oluşmasını önler; eşzamanlı denetim süreç sırasında, geri besleme denetimi süreç sonunda yapılır.'),
  ('Bir fabrikada üretim hattında ürün kontrolörünün üretim devam ederken hataları anında yakalaması hangi denetim türüdür?', 'Eşzamanlı (anlık) denetim', ['Önleyici (ileri besleme) denetim', 'Geri besleme denetimi', 'Yıllık finansal denetim'], 'Eşzamanlı denetim süreç sürerken yapılır ve sapmayı anında düzeltmeye izin verir; geri besleme denetimi sonuç ortaya çıktıktan sonra devreye girer.'),
  ('Henri Fayol\'un yönetim fonksiyonlarını ve ilkelerini ele aldığı \'Genel ve Endüstriyel Yönetim\' adlı eseri hangi yılda yayımlanmıştır?', '1916', ['1832', '1950', '1988'], 'Fayol, 1916\'da yayımladığı eserinde yönetimi planlama, örgütleme, emretme, koordinasyon ve kontrol olarak tanımlamış, on dört yönetim ilkesi önermiştir.'),
  ('Hawthorne araştırmaları hangi şirketin hangi tesisinde yürütülmüştür?', 'Western Electric\'in Hawthorne fabrikasında', ['Ford\'un Detroit fabrikasında', 'Toyota\'nın Nagoya fabrikasında', 'General Motors\'un Flint fabrikasında'], 'Elton Mayo ve ekibi 1920\'lerin sonu ile 1930\'ların başında Western Electric\'in Hawthorne fabrikasında aydınlatma ve çalışma koşullarının verime etkisini inceledi.'),
  ('Hawthorne araştırmalarında aydınlatma düzeyi değiştirildiğinde bile verimin artması neyle açıklanmıştır?', 'İlgi gördüklerini hissetmeleriyle', ['Lambaların daha parlak olmasıyla birlikte göz yorgunluğunun azalmasıyla', 'Ücretlerin iki katına çıkarılması ve primlerin artırılmasıyla birlikte', 'Makinelerin yenilenmesi ve üretim hızının artırılmasıyla birlikte'], 'Araştırmacılar, gözlenen çalışanların ilgi ve önem görmesinin verimi artırdığını, yani sosyal ve psikolojik faktörlerin fiziksel koşullar kadar etkili olduğunu görmüştür.'),
  ('Michael Porter\'ın \'Rekabet Stratejisi\' kitabı hangi on yılda yayımlanmış ve hangi çerçeveyi yaygınlaştırmıştır?', '1980\'lerin başında; beş güç analizi ve jenerik stratejiler', ['1910\'larda; bilimsel yönetim ve zaman etütleri', '1960\'larda; insan ilişkileri ve güdüleme kuramları', '2000\'lerde; yalın girişim ve MVP yaklaşımı'], 'Porter\'ın \'Competitive Strategy\' kitabı 1980\'de yayımlanmış, sektör analizi için beş güç modelini ve üç jenerik stratejiyi geniş kitlelere ulaştırmıştır.'),
  ('Hammer ve Champy\'nin 1993\'te savunduğu \'yeniden mühendislik\' yaklaşımı ne öneriyor?', 'Süreçlerin sıfırdan ve köklü yeniden tasarımı', ['Küçük adımlarla sürekli ve kademeli iyileştirmeyi sağlamayı', 'Çalışanların işini sürekli değiştirerek verim aramayı', 'Üretim hattını kapatıp tamamen ihracata yönelmeyi'], 'İş süreçlerinin yeniden mühendisliği, maliyet, kalite, hız ve hizmet göstergelerinde dramatik iyileştirme için mevcut süreçleri sıfırdan tasarlamayı önerir; kaizen ise küçük ve sürekli iyileştirmedir.'),
  ('Bir telefon satıcısının ürünle birlikte ücretsiz kurulum, uzatılmış garanti ve teslimat hizmeti sunması Kotler\'in hangi ürün düzeyidir?', 'Genişletilmiş ürün', ['Çekirdek fayda, çünkü hizmetin temelidir', 'Temel ürün, çünkü fiziksel özelliklerdir', 'Potansiyel ürün, çünkü gelecekte olabilecek yenilikleri kapsar'], 'Genişletilmiş ürün, rakiplerden ayrışmak için eklenen kurulum, garanti, teslimat ve satış sonrası hizmetlerden oluşur.'),
  ('Bir firmanın ürünlerini kendi sahip olduğu üretim, toptan ve perakende halkalarının hepsini tek çatı altında yöneterek dağıttığı kanal yapısı hangisidir?', 'Kurumsal dikey pazarlama sistemi', ['Sözleşmeli dikey pazarlama sistemi, çünkü bağımsız firmalar sözleşme yapar', 'Yönetilen dikey pazarlama sistemi, çünkü lider firma gücüyle yönetir', 'Geleneksel kanal, çünkü kanal üyeleri bağımsızdır'], 'Kurumsal dikey sistemde zincirin birbirini izleyen halkaları aynı sahibe aittir; sözleşmeli sistemde bağımsız firmalar sözleşmeyle bir araya gelir.'),
  ('Bir sadakat programının başarısız olmasının en olası nedenlerinden biri hangisidir?', 'Ödüllerin çekici olmaması ya da çok zor kazanılması', ['Ödüllerin gerçekten ulaşılabilir ve değerli olması durumunda bile', 'Programın kolayca anlaşılması ve herkes tarafından bilinmesi durumunda', 'Müşterinin puanı çok hızlı kullanabilmesi durumunda dahi'], 'Ödül algılanan değer yaratmazsa ya da ulaşılması çok zorsa müşteri programa katılmaz ve sadakat artmaz.'),
  ('Tek çatı marka stratejisinin başlıca avantajı hangisidir?', 'Güven aktarılması ve tanıtım maliyetinin düşmesi', ['Her ürünün birbirinden tamamen bağımsız kalıp itibarını ayrı kurması', 'Bir üründeki sorunun diğer ürünleri hiç etkilememesi ve yayılmaması', 'Her ürün için ayrı ve yüksek bütçeli tanıtım gerektirmesi durumu'], 'Ortak ad, yeni ürüne hazır bir tanınırlık ve itibar kazandırır; ancak bir ürünün başarısızlığı tüm markaya yayılabilir.'),
  ('Bir markanın sorunlu ürün geri çağırması sonrası itibarını onarmak için en etkili ilk adım hangisidir?', 'Hızlı, açık ve sorumluluk alan iletişim', ['Sorunu inkâr edip kamuoyuna tamamen sessiz kalmak ve beklemek', 'Suçu tüketicilere yükleyip kendi payını kabul etmemek ve savunmak', 'Reklamı kesip pazardan tamamen çekilmek ve ürünü satışa vermemek'], 'Kriz iletişiminde hız, şeffaflık ve sorumluluk güveni korur; inkâr ve geç açıklama itibar kaybını büyütür.'),
  ('Marka lisanslamada lisans veren firma lisans alana ne karşılığında kullanım hakkı tanır?', 'Genellikle satışlar üzerinden royalti ödemesi karşılığında', ['Ürünün patent hakkını tamamen devrederek', 'Hiçbir ödeme almadan ve denetim yapmadan', 'Yalnızca firmanın borçlarını devralarak'], 'Lisanslama sözleşmesinde lisans alan, markayı kullanmak için sabit bedel ve/veya satış üzerinden royalti öder; lisans veren kalite denetimini elinde tutar.'),
  ('Özel markalı (market markası) ürünlerin perakendeciye sağladığı başlıca avantaj hangisidir?', 'Daha yüksek marj ve mağaza sadakati', ['Daha az raf alanı kullanıp mağaza düzenini sadeleştirmesi ve boş alan açması', 'Üretici markalarına bağımlılığı artırıp pazarlık gücünü azaltması ve yönetmesi', 'Müşteri verisini azaltıp mağazada kalma süresini düşürmesi ve toplaması'], 'Perakendeci özel markada aracı payını ve reklam masrafını azaltarak marjı artırır; ayrıca ürünü yalnız kendi mağazasında sattığı için müşteriyi bağlar.'),
  ('Bir ürünün \'yaşam eğrisi\' yerine \'moda döngüsü\' ile açıklanabilen ürün türü hangisidir?', 'Giysi ve takı gibi zevk ve eğilimlere bağlı ürünler', ['Çimento ve çelik gibi ara malları', 'Kâğıt ve bakır gibi hammaddeleri', 'Elektrik ve su gibi kamu hizmetlerini'], 'Moda ürünleri eğilimlerin gelip geçmesiyle ani yükselen ve düşen taleple, kısa ve düzensiz döngüler yaşar; standart ara mallarda bu görülmez.'),
  ('Kamu işletmelerinin özelleştirilmesiyle en çok hangi sonucun beklenmesi gerekçelendirilir?', 'Verimlilik artışı ve mali yükün azalması', ['Fiyatların her koşulda ve her sektörde kesinlikle düşmesi', 'Çalışan sayısının daima ve her durumda artırılması gerekliliği', 'Rekabetin tamamen ortadan kalkıp tekel oluşması ihtimali'], 'Özelleştirmenin savunucuları, özel sektör yönetiminin verimlilik ve maliyet disiplini getireceğini ve gelir sağlayacağını savunur; sonuçlar sektöre ve düzenlemeye bağlıdır.'),
  ('Kooperatiflerde kâr dağıtımının temel ölçütü nedir?', 'Ortakların kooperatifle yaptığı işlem hacmi', ['Ortakların hisse sayısı', 'Ortakların yaşı', 'Ortakların kıdemi'], 'Kooperatiflerde sermayeye sınırlı faiz verilir; artı gelir genellikle ortakların kooperatifle yaptığı işlem miktarına göre dağıtılır.'),
  ('İşletmenin amaçları arasında \'kâr elde etmek\' ile \'toplumsal fayda sağlamak\' çatışırsa en doğru yaklaşım hangisidir?', 'Uzun vadede ikisini dengelemek', ['Toplumsal faydayı tamamen yok saymak', 'Kâr elde etmeyi hiç düşünmeyip yalnızca bağış yapmak ve yardımcı olmak', 'Yalnızca yöneticilerin kişisel çıkarına bakıp diğerlerini dinlememek'], 'Paydaş yaklaşımı, kâr ile toplumsal beklentilerin dengelenmesini önerir; toplum güvenini yitiren firma uzun vadede kâr da kaybedebilir.'),
  ('Bir işletmede müşteriye yönelik ürünlerin geliştirilmesi, üretilmesi, finanse edilmesi ve pazarlanması gibi temel faaliyetlerin birbirine bağlı yürütülmesi hangi görüşü yansıtır?', 'İşletmeye sistem yaklaşımıyla bakmayı', ['Yalnızca insan ilişkileri yaklaşımını', 'Yalnızca bilimsel yönetimi', 'Yalnızca bürokrasi anlayışını'], 'Sistem yaklaşımı işletmeyi birbirine bağımlı alt sistemlerden oluşan, çevresiyle etkileşen bir bütün olarak ele alır.'),
  ('Bir sektörde rakip sayısı çok, ürünler benzer ve fiyat rekabeti yoğunsa Porter\'ın beş güç modelinde sektör çekiciliği için ne söylenebilir?', 'Rekabet güçlü, kârlılık baskı altında', ['Kâr marjları kendiliğinden yüksek ve rekabet zayıf kalır ve artar', 'Yeni girişler imkânsızdır ve mevcut firmalar rahat eder', 'Alıcıların hiç pazarlık gücü yoktur ve fiyatlar istenen düzeydedir'], 'Yüksek sektör içi rekabet fiyatları aşağı çeker ve kâr potansiyelini azaltır; bu da sektörü daha az cazip kılar.'),
  ('Birçok küçük müşterinin bulunduğu bir sektörde alıcıların pazarlık gücü genel olarak nasıldır?', 'Düşüktür, çünkü tek tek satıcıyı etkileyemezler', ['Yüksektir, çünkü her müşteri fiyat belirler', 'Sıfırdır, çünkü fiyatı devlet belirler', 'Sınırsızdır, çünkü ürün zorunludur'], 'Alıcıların pazarlık gücü, az sayıda ve büyük alım yapan müşteride yüksek, çok sayıda küçük müşteride düşüktür.'),
  ('Tedarikçilerin pazarlık gücünün yüksek olduğu durum aşağıdakilerden hangisidir?', 'Az tedarikçi, ikamesiz girdi', ['Girdiyi sağlayan çok sayıda firma bulunması ve rekabet etmeleri durumu', 'Girdinin kolayca başka malla ikame edilebilmesi ve değiştirilmesi durumu', 'Alıcı sektörün tedarikçinin tek müşterisi olması ve bağımlı olması durumu'], 'Az sayıda tedarikçi, önemli ve ikamesi zor bir girdi sunuyorsa fiyat ve koşullar konusunda üstün konumdadır.'),
  ('İkame ürün tehdidinin yüksek olduğu bir sektörde firmaların fiyat politikası nasıl etkilenir?', 'Fiyat ikame fiyatıyla sınırlanır', ['Fiyatlar sınırsız artırılabilir ve talep bundan etkilenmez ve düşmez', 'Fiyat rekabeti ortadan kalkar ve bütün firmalar aynı fiyatı uygular', 'Maliyet kontrolü gereksizleşir ve verimlilik baskısı tamamen kalkar'], 'Müşteri daha ucuz ya da benzer işlevli bir ikame bulabiliyorsa firma zam yapmakta zorlanır ve sektör kârı sınırlı kalır.'),
  ('Bütünleşik pazarlama iletişiminin (BPİ) temel ilkesi nedir?', 'Tüm iletişim araçlarında tutarlı mesaj', ['Her araçta birbirinden bağımsız ve farklı mesajlar vermek, çünkü çeşitlilik ilgi çeker', 'Yalnızca televizyon reklamına yatırım yapmak, çünkü en geniş kitleye ulaşır', 'İletişim bütçesini her yıl sıfırlayıp baştan başlamak, çünkü yenilik önemlidir'], 'BPİ; reklam, halkla ilişkiler, satış geliştirme ve dijital kanallarda aynı marka mesajını tutarlı ve birbirini destekler biçimde vermeyi amaçlar.'),
  ('Uzman bir kişinin ilettiği mesajın daha ikna edici bulunması hangi iletişim ilkesine dayanır?', 'Kaynağın inandırıcılığı', ['Mesajın uzunluğu ve karmaşıklığı', 'İletişim kanalının fiyatı', 'Alıcının yaşı ve mesleği'], 'İkna araştırmaları kaynağın uzmanlık, güvenilirlik ve çekiciliğinin mesajın etkisini artırdığını gösterir.'),
  ('Mizah çekiciliğinin reklamdaki olası sakıncası nedir?', 'Markanın unutulması riski', ['Hiçbir kitleye hitap etmemesi', 'Yasal olarak yasaklanmış olması', 'Maliyetinin her zaman çok yüksek olması'], 'Komik reklam izlenir ve paylaşılır ancak izleyici esprisini hatırlayıp markayı unutabilir; mizah, ürünle bağlantılı olmalıdır.'),
  ('Dergi reklamlarının gazete reklamlarına göre başlıca avantajı hangisidir?', 'Hedef kitle seçiciliği', ['Günlük yayımlanması', 'Çok daha ucuz olması', 'Anlık duyuru için ideal olması'], 'Dergiler ilgi alanına göre okur kitlesi seçmeyi ve kaliteli baskıyı sağlar, ancak yayın aralıkları uzundur.'),
  ('Halkla ilişkiler faaliyetleri reklamdan hangi bakımdan ayrılır?', 'Ücretsiz yer, inandırıcılık', ['Her zaman daha pahalıdır', 'Yalnızca yazılı basına yönelir', 'Tamamen kontrol edilebilir'], 'Haber ve etkinliklerle kazanılan medya yer alışı, ücretli reklama göre daha tarafsız göründüğünden güven yaratır, ancak içerik üzerinde kontrol azdır.'),
  ('Bir firmanın kriz döneminde medyaya tek bir sözcü aracılığıyla tutarlı açıklama yapması hangi ilkeye dayanır?', 'Tek ses ilkesi', ['Çoklu bilgi ilkesi', 'Dağıtım ilkesi', 'Fiyat ilkesi'], 'Kriz iletişiminde farklı kişilerin farklı şeyler söylemesi güveni zedelediğinden tek yetkili sözcü ve tutarlı mesaj esastır.'),
  ('Aracılara yönelik ticari satış geliştirme araçlarından biri hangisidir?', 'Ticari iskonto ve sergileme desteği', ['Tüketiciye verilen kupon ve indirim çeki', 'Hediye çekilişi ve ödüllü yarışma', 'Ürün numunesi dağıtımı ve deneme paketi'], 'Ticari tutundurma, perakendecileri ve toptancıları ürünü stoklamaya ve öne çıkarmaya özendirmeyi amaçlar; kupon ve numune tüketiciye yöneliktir.'),
  ('Havayolları ve oteller boş koltuk ve odaları değerlendirmek için fiyatı talebe göre değiştirir. Bu uygulamaya ne ad verilir?', 'Gelir yönetimi', ['Hasat stratejisi uygulaması', 'Kaymak fiyatlama stratejisi', 'Planogram ile raf düzeni'], 'Gelir yönetimi, stoklanamayan hizmetlerde talebin yoğunluğuna göre fiyat ve kapasiteyi ayarlayarak toplam geliri en üst düzeye çıkarmaya çalışır.'),
  ('Hizmet kurtarma (service recovery) uygulamasının amacı nedir?', 'Müşteriyi memnun edip kaybı önlemek', ['Hizmeti tamamen durdurmak', 'Müşteri şikâyetini görmezden gelmek', 'Hata yapan çalışanı hemen işten çıkarmak'], 'Etkili hizmet telafisi (özür, çözüm, tazminat) hatadan sonra müşteri sadakatini bazen hatasız hizmetten daha çok artırabilir.'),
  ('Bir müşteri bekleme kuyruğunda, ne kadar bekleyeceği bilinmediğinde sabırsızlık artıyorsa hangi hizmet yönetimi önlemi alınmalıdır?', 'Tahmini bekleme süresini bildirmek', ['Müşteriye hiçbir bilgi vermemek', 'Kuyruğu görünmez yapıp bilgi saklamak', 'Kasayı bütünüyle kapatmak'], 'Belirsizlik beklemeyi daha uzun hissettirir; tahmini süre vermek ve oyalayıcı unsurlar sunmak algılanan bekleme süresini kısaltır.'),
  ('Hizmet pazarlamasında \'insan\' unsurunun önemi neden büyüktür?', 'Kalite sunan kişiye bağlıdır', ['Hizmetlerin her zaman makine tarafından sunulması nedeniyle', 'Çalışanların yalnızca fiyatı belirlemesi nedeniyle', 'Hizmetin stokta tutulması nedeniyle'], 'Hizmetin üretimi ve tüketimi eşzamanlı olduğundan, çalışanın davranışı doğrudan müşteri deneyimini belirler; seçme ve eğitim kritik hale gelir.'),
  ('Bir bankanın internet şubesine geçişi hızlandırmak için çevrim içi işlemlerde ücret almaması, hangi pazarlama stratejisine örnektir?', 'Fiyat teşviki ile yönlendirme', ['Yoğun dağıtım stratejisi uygulaması', 'Hasat stratejisi uygulaması', 'Kaymak fiyatlama stratejisi uygulaması'], 'Fiyat farkı, müşteriyi daha düşük maliyetli kanala yönlendirmek için bir teşvik aracı olarak kullanılır.'),
  ('Fiyat esnekliğinin mutlak değeri 2,5 ise fiyatın %4 artması talep miktarını yaklaşık yüzde kaç değiştirir?', '%10 azaltır', ['%10 artırır', '%1,6 azaltır', '%4 azaltır'], 'Miktar değişimi = −2,5 × %4 = −%10; fiyat arttığında talep azalır.'),
  ('Bir kampanya 40.000 TL\'ye mal olmuş ve ek brüt kâr 52.000 TL getirmiştir. Pazarlama yatırım getirisi (ROMI) yüzde kaçtır?', '30', ['23', '130', '12'], 'ROMI = (ek brüt kâr − maliyet) / maliyet = (52.000 − 40.000) / 40.000 = %30.'),
  ('Müşteri edinme maliyeti 150 TL, müşterinin ömür boyu brüt kâr katkısı 600 TL ise CLV/CAC oranı kaçtır?', '4', ['0,25', '450', '3'], 'Oran = 600 / 150 = 4; genel kabule göre oran 3\'ün üzerindeyse model sağlıklı sayılır.'),
  ('Bir ürünün satışları artarken pazar payı düşüyorsa bu durum neyi gösterir?', 'Pazarın firmadan hızlı büyüdüğünü', ['Pazarın küçüldüğünü', 'Rakiplerin pazardan çekildiğini', 'Müşteri memnuniyetinin %100 olduğunu'], 'Firma büyüse bile pazar daha hızlı büyüyorsa payı azalır; pazar payı göreli bir göstergedir.'),
  ('Bir marka bilinirliği anketinde \'yardımsız bilinirlik\' neyi ölçer?', 'Marka adının ipucu verilmeden hatırlanmasını', ['Marka adının listeden tanınmasını', 'Markanın satın alınmasını', 'Markaya sadakati'], 'Yardımsız bilinirlik, kişinin kategoriyi duyunca markayı kendiliğinden anmasıdır; yardımlı bilinirlikte ise marka adı gösterilir.'),
  ('Aynı ürün 80 TL\'den 100 TL\'ye çıkarılınca satış 500\'den 400 adede düşmüştür. Toplam gelir nasıl değişmiştir?', '40.000 TL\'de kalmıştır', ['8.000 TL artmıştır', '10.000 TL azalmıştır', '5.000 TL artmıştır'], 'Önce 80 × 500 = 40.000 TL; sonra 100 × 400 = 40.000 TL; talep birim esnek olduğundan gelir değişmemiştir.'),
  ('İş Kanunu\'na göre yıllık ücretli izin süresi, hizmet süresi 1 yıl dolmuş ve 5 yıldan az olan işçi için en az kaç gündür?', '14', ['10', '20', '26'], 'Yıllık izin 1-5 yıl arası için 14, 5-15 yıl için 20, 15 yıl ve üzeri için 26 gündür.'),
  ('İş Kanunu\'na göre işçiye bir iş haftası içinde kesintisiz en az kaç saat hafta tatili verilmelidir?', '24', ['12', '36', '48 saat'], 'İşçiye haftada en az 24 saat dinlenme (hafta tatili) verilmesi zorunludur.'),
  ('Bir işveren çalışanının kendi isteği dışında iş sözleşmesini haklı bir neden göstermeden sona erdirmesi hâlinde işçi hangi hukuki yola başvurabilir?', 'İş mahkemesinde işe iade davası', ['Rekabet Kurumuna ve Rekabet Kurulu\'na şikâyet başvurusu', 'Vergi dairesine itiraz dilekçesi ve beyanname düzeltmesi', 'Borsa Kurulu\'na başvuru ve hisse senedi tescili'], 'Belirli koşullarda iş güvencesi kapsamındaki işçi, geçersiz feshe karşı arabulucuya ve ardından iş mahkemesine başvurarak işe iade talep edebilir.'),
  ('Çalışanın iş yerinde uğradığı kaza ya da meslek hastalığının tazmini hangi sigorta kolunun kapsamındadır?', 'İş kazası ve meslek hastalığı sigortası', ['Genel sağlık sigortası yalnızca ve tek başına', 'İşsizlik sigortası fonu ve iş arama ödeneği', 'Bireysel emeklilik sistemi ve devlet katkısı'], 'İş kazası ve meslek hastalığı sigortası, çalışanı iş yerinde karşılaşılan riskler için tedavi, geçici iş göremezlik ve sürekli iş göremezlik ödenekleriyle korur.'),
  ('Sektör yaşam döngüsünün \'giriş\' aşamasında rekabet ve kârlılık için hangisi geçerlidir?', 'Rakip az, talep belirsiz ve kârlılık düşüktür', ['Rakip çok, talep doygun ve kâr yüksektir', 'Rakiplerin çoğu sektörden çıkmıştır', 'Fiyat savaşları en yoğun düzeydedir'], 'Yeni sektörlerde teknoloji ve talep belirsizdir; az sayıda firma yüksek yatırımla çalışır ve kâr genellikle düşüktür.'),
  ('Sektörün olgunluk aşamasında firmaların rekabet için sık başvurduğu yöntem hangisidir?', 'Maliyet düşürme ve pazar payını savunma', ['Hiç reklam yapmama', 'Üretimi tamamen durdurma', 'Fiyatları sürekli artırma'], 'Olgun sektörlerde büyüme yavaşladığından firmalar verimlilik, maliyet liderliği ve mevcut payı koruma yoluna gider; birleşmeler de yaygındır.'),
  ('Sektörde kalma kararını zorlaştıran ve zarar eden firmaların bile çıkamamasına yol açan unsurlara ne ad verilir?', 'Çıkış engelleri', ['Giriş engelleri', 'Satış engelleri', 'Dağıtım engelleri'], 'Özel amaçlı yatırımlar, işçi tazminatları ve duygusal bağlılık gibi çıkış engelleri aşırı kapasite ve düşük kâr döngüsünü uzatır.'),
  ('Aynı sektörde benzer stratejiler izleyen firmaların oluşturduğu gruba ne ad verilir?', 'Stratejik grup', ['Konsorsiyum', 'Kartel', 'Holding'], 'Stratejik gruplar sektörü benzer fiyat, ürün genişliği ve dağıtım tercihleri olan firma kümelerine ayırır; gruplar arası hareket engellerle sınırlıdır.'),
  ('Bir firmanın zarardan çıkmak için maliyet kısma, varlık satışı ve çekirdek işe dönme gibi adımlar atmasına ne ad verilir?', 'Toparlanma (turnaround) stratejisi', ['Dikey bütünleşme stratejisi', 'Çeşitlendirme stratejisi', 'Lisanslama stratejisi'], 'Toparlanma stratejisi, düşen performansı tersine çevirmek için kısa sürede yeniden yapılanma ve maliyet disiplini uygular.'),
  ('Birleşme sonrası entegrasyonda en sık karşılaşılan sorunlardan biri hangisidir?', 'Örgüt kültürlerinin uyuşmaması', ['Ürün fiyatlarının otomatik düşmesi', 'Hissedarların hiç değişmemesi', 'Rakiplerin ortadan kalkması'], 'Birçok birleşme, kültür ve yönetim tarzı farkları nedeniyle beklenen sinerjiyi sağlayamaz; entegrasyon planı bu yüzden kritiktir.'),
  ('Kaynak temelli bakış (RBV) açısına göre sürdürülebilir üstünlüğün kaynağı nedir?', 'Değerli, nadir ve taklit edilmesi zor kaynaklar', ['Yalnızca düşük fiyat', 'Yalnızca reklam bütçesi', 'Yalnızca rakip sayısı'], 'RBV üstünlüğü firmanın sahip olduğu özgün kaynak ve yeteneklere bağlar; VRIO çerçevesi bu kaynakları sınar.'),
  ('Bir stratejinin uygulanabilmesi için hangi öğeler genellikle strateji ile uyumlu olmalıdır?', 'Örgüt yapısı, süreçler, insan kaynağı ve kültür', ['Yalnızca reklam afişi', 'Yalnızca vergi oranları', 'Yalnızca rakiplerin planı'], 'İyi formüle edilmiş strateji bile yapı, sistem, insan ve kültür uyumsuzluğu yüzünden uygulanamaz; 7S modeli bu uyuma işaret eder.'),
  ('Anahtar başarı faktörleri (ASF) kavramı neyi ifade eder?', 'Rekabet için gereken kritik beceri ve kaynaklar', ['Bir firmanın bütün giderlerinin ve borçlarının toplam listesi', 'Şirket çalışanlarının unvan ve maaş bilgilerinin listesi', 'Reklam harcamalarının yıllık toplamı ve medya dağılımı'], 'ASF; maliyet, kalite, dağıtım, marka ya da teknoloji gibi bir sektörde başarının belirleyici unsurlarıdır ve sektöre göre değişir.'),
  ('Bir sektörde ürünler birbirinin aynısıysa ve müşteri geçiş maliyeti yoksa firmanın en çok hangi alanda rekabet etmesi beklenir?', 'Fiyat', ['Ürün tasarımı', 'Marka hikâyesi', 'Ambalaj rengi'], 'Ürün farklılaşması ve geçiş maliyeti olmadığında müşteri en ucuz olanı seçer; bu yüzden fiyat rekabeti baskın olur.'),
  ('Garanti belgesi düzenlenmesi zorunlu olan bir üründe satıcının/üreticinin tüketiciye karşı yükümlülüğü ne anlama gelir?', 'Ürünün belirli süre arızalarını ücretsiz gidermeyi taahhüt etmesi', ['Ürünün her koşulda iade alınacağı', 'Fiyatın sabit kalacağı', 'Tüketicinin vergi ödemeyeceği'], 'Garanti süresi içinde malın arızası işçilik, malzeme ve değiştirilen parça ücreti alınmadan giderilir; süre teslimden başlar.'),
  ('Ürün üzerindeki CE işareti neyi gösterir?', 'AB teknik düzenlemelerine uygunluk', ['Ürünün Avrupa\'da üretildiğinin belgesi ve menşe işareti olması', 'Ürünün ihracatının yasak olduğunu gösteren uyarı işareti', 'Ürünün ücretsiz verildiğini gösteren promosyon işareti'], 'CE işareti, ürünün sağlık, güvenlik ve çevre gereksinimlerine uyduğunun üretici beyanıdır; menşe belirtmez.'),
  ('Satıcının ürün etiketinde yazılı fiyattan daha yüksek fiyat talep etmesi tüketici hukuku açısından nasıl değerlendirilir?', 'Etiket fiyatı tüketici lehine uygulanır', ['Satıcı kasada istediği yüksek fiyatı alabilir ve ürünü satabilir', 'Etiket yalnızca öneri niteliğindedir ve bağlayıcı sayılmaz', 'Kasadaki fiyat her koşulda geçerlidir ve tartışılamaz'], 'Fiyat etiketi satıcıyı bağlar; etiket ile kasa fiyatı farklıysa tüketici lehine olan fiyat uygulanır.'),
  ('Reklamlarda \'sınırlı sayıda\' ya da \'son gün\' ifadelerinin gerçeğe aykırı kullanılması hangi uygulamaya girer?', 'Haksız ticari uygulama', ['Rekabet ihlali yalnızca', 'Vergi kaçakçılığı', 'Marka tescili'], 'Tüketiciyi gerçeğe aykırı aciliyet ya da kıtlık izlenimiyle yönlendirmek yanıltıcı ticari uygulamadır ve yaptırıma tabidir.'),
  ('Satıcının malın ayıplı çıkması durumunda tüketicinin seçimlik haklarından biri hangisi değildir?', 'Satıcıdan dilediği kadar tazminat cezası almak', ['Sözleşmeden dönme', 'Bedel indirimi isteme', 'Ayıpsız misliyle değiştirme'], 'Ayıplı malda dönme, indirim, ücretsiz onarım ve değiştirme hakları vardır; sınırsız bir ceza talebi seçimlik hak değildir.'),
  ('Çocuklara yönelik reklamlarda hassas davranılmasının temel gerekçesi nedir?', 'Çocukların ikna girişimlerini ayırt etme ve eleştirme kapasitesinin sınırlı olması', ['Çocukların fazla para harcaması', 'Çocukların reklam izlememesi', 'Çocukların reklamı hiç hatırlamaması'], 'Gelişim dönemindeki çocuklar reklamın ticari amacını kavramakta zorlanabilir; bu yüzden sınırlama ve ek sorumluluk getirilir.'),
  ('İnternet üzerinden satın alınan, kişiye özel üretilen bir ürün için cayma hakkı konusunda ne söylenebilir?', 'Kişiye özel ürünlerde cayma hakkı yoktur', ['Her ürünle aynı biçimde ve aynı süreyle kullanılır ve kısıtlanmaz', 'Süre sınırsızdır ve tüketici dilediği zaman kullanır ve iade eder', 'Satıcı ödeme almadan teslim eder ve cayma süreci hiç başlamaz'], 'Mesafeli sözleşmelerde tüketicinin istekleri ya da kişisel ihtiyaçları doğrultusunda hazırlanan mallar cayma hakkı kapsamı dışındadır.'),
  ('Tüketici kredisi ya da taksitli satışlarda \'efektif yıllık faiz oranı\' neyi gösterir?', 'Tüm masraflarla birlikte yıllık gerçek maliyeti', ['Yalnızca ilan edilen aylık faizi', 'Kredi tutarının yarısını', 'Bankanın vergisini'], 'Efektif oran, faiz dışında komisyon, sigorta ve ücretleri de dikkate alarak kredinin yıllık toplam maliyetini ifade eder.'),
  ('Doğrudan satış ve piramit satış sistemlerini ayıran temel özellik nedir?', 'Piramitte kazanç yeni üyeden gelir', ['Doğrudan satışta kimsenin hiç kazanç elde etmemesi ve zarar etmesi', 'Piramitte gerçek ürün satışının çok yüksek ve belgeli olması', 'İkisinin birbiriyle aynı olması ve yasal farkın bulunmaması'], 'Piramit sistemlerde gelir ürün satışından değil, yeni katılımcıların ödemelerinden gelir; sistem sürdürülemez ve çoğu ülkede yasaktır.'),
  ('Reklam verenin ürünün özelliklerine ilişkin iddialarını kanıtlayamaması hâlinde ne olur?', 'Durdurma ve idari yaptırım', ['Hiçbir sonuç doğmaz ve reklam yayınlanmaya devam eder', 'İddia otomatik olarak doğru sayılır ve ispat aranmaz', 'Ürün tüm tüketicilere ücretsiz olarak dağıtılmak zorunda kalır'], 'Reklam Kurulu, iddiaların ispatını reklam verenden isteyebilir; ispatlanamazsa durdurma ve idari para cezası uygulanır.'),
  ('Bir mağazanın etiket fiyatını \'indirimli\' göstermek için önce fiyatı yükseltip sonra indirim yapması hangi sorunu doğurur?', 'Yanıltıcı fiyatlandırma', ['Dampingle satış yapma uygulaması', 'Vergi iadesi alma uygulaması', 'Franchise sözleşmesi yapma uygulaması'], 'İndirimden önce fiyatın yapay biçimde artırılması, tüketiciye gerçek olmayan bir tasarruf izlenimi verdiği için yanıltıcı uygulamadır.'),
  ('Chesbrough\'un \'açık inovasyon\' yaklaşımının temel fikri nedir?', 'Dış fikirleri de kullanıp kendi fikrini açmak', ['Tüm Ar-Ge çalışmasını yalnızca şirket içinde ve gizli yürütmek', 'Patent almaktan tamamen kaçınıp bütün fikirleri bedava dağıtmak', 'Yenilik yapmaktan vazgeçip yalnızca mevcut ürünle yetinmek'], 'Açık inovasyonda firmalar ortaklık, lisans, kitle kaynak ve girişim yatırımlarıyla dış bilgiyi içeri, kullanılmayan fikirleri dışarı taşır.'),
  ('Tasarım odaklı düşünmede \'prototip\' aşamasının amacı nedir?', 'Fikri hızlı ve ucuz biçimde somutlaştırıp kullanıcıyla sınamak', ['Fikrin patentini almak', 'Üretim hattını kurmak', 'Ürünü ihraç etmek'], 'Prototip, tam ölçekli yatırımdan önce fikri düşük maliyetle somutlaştırıp geri bildirim almayı sağlar.'),
  ('Kitle kaynak (crowdsourcing) uygulaması hangi durumda yaşanır?', 'Bir firmanın sorununu geniş bir topluluğa duyurup çözüm toplaması', ['Firmanın tüm işini tek bir uzmana vermesi', 'Firmanın hisse senedini halka arz etmesi', 'Firmanın işini tamamen durdurması'], 'Crowdsourcing; yarışma, öneri platformu ya da açık çağrı yoluyla çok sayıda kişiden fikir, içerik ya da çözüm toplamaktır.'),
  ('SCAMPER tekniğindeki \'S\' (Substitute) neyi hatırlatır?', 'Bir bileşeni ya da malzemeyi başkasıyla değiştirmeyi', ['Satışı artırmayı', 'Stoku azaltmayı', 'Çalışanı değiştirmeyi'], 'SCAMPER; değiştir, birleştir, uyarla, değiştirip büyüt/küçült, başka kullanım, çıkar ve tersine çevir sorularıyla yaratıcı fikir üretmeyi destekler.'),
  ('De Bono\'nun \'altı şapka\' yönteminde kırmızı şapka hangi düşünme biçimini temsil eder?', 'Duygular ve sezgiler', ['Bilgi ve veriler', 'Olumlu yanlar', 'Eleştirel risk analizi'], 'Beyaz şapka veri, kırmızı şapka duygu, siyah şapka eleştiri, sarı şapka fayda, yeşil şapka yaratıcılık, mavi şapka süreç yönetimini temsil eder.'),
  ('Bir ustanın yıllarca edindiği beceriyi yazıya dökmenin güç olması hangi bilgi türünün özelliğidir?', 'Zımni (örtük) bilgi', ['Açık bilgi', 'Kamusal bilgi', 'Kodlanmış bilgi'], 'Zımni bilgi kişisel deneyime dayanır, ifade edilmesi zordur ve çoğunlukla gözlem ile birlikte çalışarak aktarılır.'),
  ('Aynı mesleği yapan kişilerin deneyim ve uygulamalarını paylaştığı gayriresmî öğrenme topluluklarına ne ad verilir?', 'Uygulama toplulukları', ['Kartel', 'Konsorsiyum', 'Sendika'], 'Uygulama toplulukları, ortak ilgi ve görev çevresinde gönüllü olarak bir araya gelip bilgi paylaşan gruplardır.'),
  ('Stage-gate (aşama-kapı) sürecinde \'kapı\' toplantılarının amacı nedir?', 'Projeye devam kararı vermek', ['Projeyi her koşulda ve incelemeden onaylayıp finanse etmek', 'Projeyi hiç incelememek ve sonucunu beklemek ve öylece bırakmak', 'Çalışanların maaşlarını ve primlerini belirleyip dağıtmak'], 'Her kapıda proje kriterlere göre değerlendirilir; devam, durdurma ya da yeniden yönlendirme kararı verilerek kaynak israfı azaltılır.'),
  ('Ar-Ge yoğunluğu hangi oranla ölçülür?', 'Ar-Ge harcamasının satışlara (ya da GSYH\'ye) oranı', ['Ar-Ge çalışanlarının toplam çalışana oranı yalnızca', 'Satışların maliyete oranı', 'Kârın özkaynağa oranı'], 'Ar-Ge yoğunluğu firmada Ar-Ge harcamasının cirosuna, ülkede ise Ar-Ge harcamasının GSYH\'ye oranıdır.'),
  ('Teknoloji transferinin ülke ya da firma için sağladığı temel fayda nedir?', 'Hazır teknolojiyle ar-ge süresini kısaltmak', ['Tüm rakipleri tamamen etkisiz kılıp pazara hâkim olmak ve büyümek', 'Vergi ödemekten tamamen kaçınmak ve devlet teşvikini artırmak', 'İşgücü ihtiyacını tamamen sıfırlayıp fabrikayı kapatmak ve çıkmak'], 'Lisans, ortak girişim ya da yabancı yatırım yoluyla teknoloji edinmek zaman kazandırır; ancak içselleştirme yeteneği şarttır.'),
  ('Bir yönetici, çalışanın gelişmesini desteklemek için ona sorular sorup kendi çözümünü bulmasına yardım ediyor. Bu uygulama hangisidir?', 'Koçluk', ['Mentorluk, çünkü deneyimli kişi yol gösterir', 'Denetim, çünkü hata aranır', 'Cezalandırma, çünkü sonuç odaklıdır'], 'Koçluk, kişinin kendi potansiyelini ortaya çıkarmasına yardım eden soru temelli bir geliştirme yöntemidir; mentorlukta ise deneyimli kişi bilgi ve tavsiye aktarır.'),
  ('Yöneticinin yetki devrederken izlemesi gereken doğru adım hangisidir?', 'Görev, beklenti ve yetkiyi açıkça belirtip sonuçları izlemek', ['Görevi belirtmeden bırakıp kontrol etmemek', 'Yetkiyi tamamen devredip sorumluluğu çalışana yüklemek', 'Yalnızca hata yapılınca devreye girmek'], 'Etkili devir; net hedef, yeterli yetki, kaynak ve geri bildirimle yapılır; nihai sorumluluk yönetici üzerinde kalır.'),
  ('Kriz yönetiminin yaygın aşamaları arasında \'kriz sinyallerinin algılanması\' hangi aşamadır?', 'Kriz öncesi hazırlık aşaması', ['Kriz sonrası toparlanma ve öğrenme aşaması', 'Pazarlama kampanyası hazırlama aşaması', 'Üretim planlaması ve stok sayımı aşaması'], 'Kriz yönetimi öncesinde belirtileri izleme, senaryo hazırlama ve eğitim yoluyla önleme çalışılır; sonra kriz anında müdahale, sonrasında toparlanma ve öğrenme gelir.'),
  ('Bir yöneticinin ekibe sık sık yeni görevler verip çalışanların önceliklerini değiştirmesi hangi sorunu doğurabilir?', 'Rol belirsizliği ve odak kaybı', ['Sinerji artışı', 'Çalışan sadakatinde sıçrama', 'Maliyetlerin kesin düşmesi'], 'Önceliklerin sürekli değişmesi çalışanın ne beklendiğini bilememesine ve verimin düşmesine yol açar.'),
  ('Takım üyeleri arasındaki ilişkilerin gelişmesi için en etkili yöntemlerden biri hangisidir?', 'Ortak hedefli görev ve açık iletişim', ['Üyeleri birbirinden tamamen ayırıp çalışma alanlarını bölmek ve ayırmak', 'Sürekli rekabeti özendirip bilgi paylaşımını yasaklamak ve engellemek', 'Yalnızca bireysel ödül verip takım hedefini görmezden gelmek ve saklamak'], 'Güven, ortak hedef ve sık iletişim takım uyumunu güçlendirir; yalnızca bireysel rekabet işbirliğini azaltabilir.'),
  ('Çok kültürlü bir ekibi yöneten kişi için en önemli yetkinlik hangisidir?', 'Kültürel farklılıklara duyarlılık ve esnek iletişim', ['Yalnızca tek dil bilmek', 'Tüm kuralları kendi kültürüne göre dayatmak', 'İletişimden kaçınmak'], 'Kültürlerarası yetkinlik, farklı değerleri anlama, önyargıdan kaçınma ve iletişim tarzını uyarlamayı kapsar.'),
  ('Bir şirkette kıdemin tek terfi ölçütü olması en çok hangi sorunu doğurur?', 'Genç yeteneklerin motivasyon kaybı', ['Çalışan sayısının sıfırlanması', 'Kıdemli çalışanların işten ayrılması', 'Maliyetin düşmesi'], 'Yalnızca kıdeme dayalı terfi başarı ve yeteneği ödüllendirmediğinden yetenekli genç çalışanlarda adaletsizlik algısı ve ayrılma eğilimi doğurabilir.'),
  ('Çalışanlara iş yerinde psikolojik güvenlik sağlanması hangi davranışı kolaylaştırır?', 'Hata ve fikri korkmadan paylaşmak', ['Hataları gizleyip yalnızca olumlu haberleri iletmek', 'Fikir üretmekten çekinip sessiz kalmayı sürdürmek', 'Bilgiyi saklayıp başkalarıyla paylaşmaktan kaçınmak'], 'Psikolojik güvenlik, ekip üyelerinin soru sormaktan, fikir önermekten ve hata bildirmekten çekinmemesi olup öğrenme ve inovasyonu artırır.'),
  ('İşletme yönetiminde \'etkinlik\' ile \'verimlilik\' arasındaki fark nedir?', 'Etkinlik doğru işi, verimlilik az kaynakla yapmaktır', ['İkisi tamamen aynı kavramdır ve aralarında fark yoktur', 'Etkinlik yalnızca maliyeti, verimlilik yalnızca hedefi ifade eder', 'Verimlilik yalnızca hedefi, etkinlik yalnızca zamanı ifade eder'], 'Drucker\'a göre etkinlik \'doğru şeyleri yapmak\', verimlilik \'şeyleri doğru yapmak\' olarak özetlenir; ikisi birbirini tamamlar.'),
];
